-- V469: Seed 144 Class 10 Social Science Mock Tests (104 Real-Format 80M Papers + 40 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class10_id UUID;
BEGIN
    SELECT id INTO v_class10_id FROM learn_exam_types WHERE slug IN ('class-10', 'cbse-class-10') LIMIT 1;
    IF v_class10_id IS NULL THEN
        SELECT id INTO v_class10_id FROM learn_exam_types WHERE name ILIKE '%Class 10%' LIMIT 1;
    END IF;

    IF v_class10_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '10030000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '10030000-%';

        ON CONFLICT (id) DO NOTHING;

Reason (R): It ruled Alpine regions, Bohemia, Lombardy-Venetia, Hungary, and Galicia speaking German, Italian, Polish, and Magyar.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'Linguistic/ethnic diversity made political unity fragile.', NULL, NULL, 'Linguistic/ethnic diversity made political unity fragile.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000007', 'What were the main provisions of the Napoleonic Code (Civil Code of 1804)?', NULL, NULL, 'VSA', 'Social Science', 'The Rise of Nationalism in Europe', 2, 'Abolished privileges based on birth, established equality before law, secured the right to property, abolished feudal system, freed peasants from serfdom, and standardised weights and measures.', 'Any 2–4 valid points (2M)', NULL, 'Abolished privileges based on birth, established equality before law, secured the right to property, abolished feudal system, freed peasants from serfdom, and standardised weights and measures.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000008', 'Who were Giuseppe Mazzini and Count Camillo de Cavour in Italian unification?', NULL, NULL, 'VSA', 'Social Science', 'The Rise of Nationalism in Europe', 2, 'Mazzini founded Young Italy to spread republican nationalism; Cavour (Prime Minister of Sardinia-Piedmont) led diplomatic alliance with France to defeat Austria in 1859.', '1M each', NULL, 'Mazzini founded Young Italy to spread republican nationalism; Cavour (Prime Minister of Sardinia-Piedmont) led diplomatic alliance with France to defeat Austria in 1859.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000009', 'How did culture (Romanticism, folk songs, language) play an important role in creating the idea of the nation in Europe?', NULL, NULL, 'SA', 'Social Science', 'The Rise of Nationalism in Europe', 3, 'Romantic artists criticised reason/science glorification and celebrated shared collective heritage via folk songs, poetry, and dances (e.g., Johann Gottfried Herder''s Das Volk, Karol Kurpinski''s operas, and Polish language resistance against Russian imposition).', 'Romanticism concept (1M) + Folk culture & Polish language example (2M)', NULL, 'Romantic artists criticised reason/science glorification and celebrated shared collective heritage via folk songs, poetry, and dances (e.g., Johann Gottfried Herder''s Das Volk, Karol Kurpinski''s operas, and Polish language resistance against Russian imposition).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000000a', 'Summarise the main decisions taken at the Congress of Vienna (1815).', NULL, NULL, 'SA', 'Social Science', 'The Rise of Nationalism in Europe', 3, 'Hosted by Metternich: Bourbon dynasty restored in France; France lost conquered territories; barrier states (Netherlands+Belgium, Genoa+Piedmont) formed around France; Prussia/Austria/Russia gained territories; German confederation of 39 states kept intact.', '3 distinct provisions × 1M', NULL, 'Hosted by Metternich: Bourbon dynasty restored in France; France lost conquered territories; barrier states (Netherlands+Belgium, Genoa+Piedmont) formed around France; Prussia/Austria/Russia gained territories; German confederation of 39 states kept intact.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000000b', 'Trace the process of German unification from 1848 Frankfurt Parliament to January 1871 at Versailles.', NULL, NULL, 'LA', 'Social Science', 'The Rise of Nationalism in Europe', 5, '1848 Frankfurt Parliament failed when Friedrich Wilhelm IV rejected the crown. Thereafter, Prussia under Chief Minister Otto von Bismarck led "blood and iron" diplomacy: three wars over seven years against Denmark, Austria, and France (1864–1870) all ended in Prussian victory. In January 1871 at Versailles Hall of Mirrors, Prussian King Kaiser William I was proclaimed German Emperor.', '1848 attempt (1.5M) + Bismarck & 3 wars (2M) + 1871 proclamation & modernisation (1.5M)', NULL, '1848 Frankfurt Parliament failed when Friedrich Wilhelm IV rejected the crown. Thereafter, Prussia under Chief Minister Otto von Bismarck led "blood and iron" diplomacy: three wars over seven years against Denmark, Austria, and France (1864–1870) all ended in Prussian victory. In January 1871 at Versailles Hall of Mirrors, Prussian King Kaiser William I was proclaimed German Emperor.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000000c', '(i) Why did the Balkans become the most serious source of nationalist tension after 1871? (ii) Name two modern Balkan states. (iii) Why did big European powers intervene in the Balkans? (iv) What global conflict did Balkan rivalry trigger?', NULL, NULL, 'CASE', 'Social Science', 'The Rise of Nationalism in Europe', 4, '(i) Ethnic Slav groups under weakening Ottoman Empire sought independence while fiercely jealous of each other. (ii) Serbia, Bulgaria, Greece, Romania (any two). (iii) Rivalry over trade, colonies, and naval/military supremacy (Russia, Germany, Britain, Austro-Hungary). (iv) First World War (1914).', '4 × 1M = 4M', 'After 1871, the Slavic peoples of the mountainous Balkan region under declining Ottoman control increasingly demanded separate nation-states, attracting intense military intervention from European Great Powers.', '(i) Ethnic Slav groups under weakening Ottoman Empire sought independence while fiercely jealous of each other. (ii) Serbia, Bulgaria, Greece, Romania (any two). (iii) Rivalry over trade, colonies, and naval/military supremacy (Russia, Germany, Britain, Austro-Hungary). (iv) First World War (1914).', 'HARD', true),
        ('10031111-0000-4000-8000-00000000000d', 'In which year did Mahatma Gandhi return to India from South Africa?', '{"A":"1913","B":"1915","C":"1917","D":"1919"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nationalism in India', 1, 'Gandhiji returned in January 1915.', NULL, NULL, 'Gandhiji returned in January 1915.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000000e', 'The Chauri Chaura incident in February 1922 led Gandhiji to withdraw the:', '{"A":"Civil Disobedience Movement","B":"Non-Cooperation Movement","C":"Quit India Movement","D":"Khilafat Agitation"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nationalism in India', 1, 'Violence at Chauri Chaura (Gorakhpur) led to halting NCM.', NULL, NULL, 'Violence at Chauri Chaura (Gorakhpur) led to halting NCM.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000000f', 'Who authored the famous book "Hind Swaraj" (1909)?', '{"A":"Jawaharlal Nehru","B":"Mahatma Gandhi","C":"Subhas Chandra Bose","D":"Bal Gangadhar Tilak"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nationalism in India', 1, 'Hind Swaraj declared British rule survived only with Indian cooperation.', NULL, NULL, 'Hind Swaraj declared British rule survived only with Indian cooperation.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000010', 'At which Congress session (December 1929) was the demand for "Purna Swaraj" formalised?', '{"A":"Nagpur","B":"Calcutta","C":"Lahore","D":"Madras"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Nationalism in India', 1, 'Lahore session under Jawaharlal Nehru declared 26 Jan 1930 Independence Day.', NULL, NULL, 'Lahore session under Jawaharlal Nehru declared 26 Jan 1930 Independence Day.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000011', 'The Poona Pact of September 1932 was signed between Mahatma Gandhi and:', '{"A":"Muhammad Ali Jinnah","B":"Dr. B.R. Ambedkar","C":"Lord Irwin","D":"Motilal Nehru"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nationalism in India', 1, 'Provided reserved seats in provincial/central councils via general electorate.', NULL, NULL, 'Provided reserved seats in provincial/central councils via general electorate.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000012', 'Assertion (A): Alluri Sitaram Raju led the militant guerrilla movement in the Gudem Hills of Andhra Pradesh.
Reason (R): Tribal people were enraged because colonial forest laws barred them from grazing cattle and collecting fuelwood.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Nationalism in India', 1, 'Forest restrictions sparked tribal uprising.', NULL, NULL, 'Forest restrictions sparked tribal uprising.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000013', 'Why did Gandhiji decide to launch a nationwide Satyagraha against the Rowlatt Act (1919)?', NULL, NULL, 'VSA', 'Social Science', 'Nationalism in India', 2, 'Passed hurriedly despite united Indian opposition, it gave British government enormous powers to repress political activities and detain political prisoners without trial for two years.', 'Unjust detention without trial (1M) + Passed despite opposition (1M)', NULL, 'Passed hurriedly despite united Indian opposition, it gave British government enormous powers to repress political activities and detain political prisoners without trial for two years.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000014', 'Who painted Bharat Mata first and how did symbols like the Swaraj flag foster collective belonging?', NULL, NULL, 'VSA', 'Social Science', 'Nationalism in India', 2, 'Abanindranath Tagore painted Bharat Mata as an ascetic calm divine figure (1905). Gandhi''s Swaraj tricolour with spinning wheel symbolised self-help and defiance.', '1M each', NULL, 'Abanindranath Tagore painted Bharat Mata as an ascetic calm divine figure (1905). Gandhi''s Swaraj tricolour with spinning wheel symbolised self-help and defiance.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000015', 'Explain how the Non-Cooperation Movement unfolded in the towns and why it slowed down gradually.', NULL, NULL, 'SA', 'Social Science', 'Nationalism in India', 3, 'Students left government schools, teachers/lawyers resigned, council elections boycotted (except Justice Party Madras), foreign cloth burnt and liquor picketed. It slowed because Khadi was costlier than mill cloth and alternative Indian schools/courts were scarce.', 'Town participation (1.5M) + Reasons for slowdown (1.5M)', NULL, 'Students left government schools, teachers/lawyers resigned, council elections boycotted (except Justice Party Madras), foreign cloth burnt and liquor picketed. It slowed because Khadi was costlier than mill cloth and alternative Indian schools/courts were scarce.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000016', 'Distinguish between the Non-Cooperation Movement (1921) and the Civil Disobedience Movement (1930).', NULL, NULL, 'SA', 'Social Science', 'Nationalism in India', 3, 'NCM aimed at non-cooperation with colonial institutions + Swaraj; CDM went further to actively break colonial laws (Salt Law, forest laws, non-payment of chowkidari tax). Women participation and peasant diversity were also wider in CDM.', '3 clear points × 1M', NULL, 'NCM aimed at non-cooperation with colonial institutions + Swaraj; CDM went further to actively break colonial laws (Salt Law, forest laws, non-payment of chowkidari tax). Women participation and peasant diversity were also wider in CDM.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000017', 'Explain the Salt March (Dandi March) and discuss how different social groups (Rich peasants, Poor peasants, Business classes, Women) participated in Civil Disobedience Movement with their distinct ideals of Swaraj.', NULL, NULL, 'LA', 'Social Science', 'Nationalism in India', 5, 'Dandi March (12 March–6 April 1930, 240 miles Sabarmati to Dandi) broke salt monopoly uniting rich and poor. Rich peasants (Patidars, Jats) wanted lower revenue; Poor peasants wanted unpaid rent remitted; Industrialists (FICCI) wanted tariff protection; Women joined marches and picketing in thousands.', 'Salt March significance (2M) + 4 social groups with aspirations (3M)', NULL, 'Dandi March (12 March–6 April 1930, 240 miles Sabarmati to Dandi) broke salt monopoly uniting rich and poor. Rich peasants (Patidars, Jats) wanted lower revenue; Poor peasants wanted unpaid rent remitted; Industrialists (FICCI) wanted tariff protection; Women joined marches and picketing in thousands.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000018', '(i) When and where did the Jallianwala Bagh massacre take place? (ii) Why had villagers gathered inside the ground? (iii) Name the British officer who ordered firing. (iv) What immediate effect did it have across northern India?', NULL, NULL, 'CASE', 'Social Science', 'Nationalism in India', 4, '(i) 13 April 1919, Amritsar. (ii) Peaceful Baisakhi fair and protest against arrest of Dr. Saifuddin Kitchlew & Dr. Satyapal. (iii) General Reginald Dyer. (iv) Strikes, clashes with police, attacks on government buildings, followed by brutal martial law.', '4 × 1M = 4M', 'On Baisakhi day, 13 April 1919, an enclosed ground in Amritsar filled with villagers unaware that martial law orders had prohibited public gatherings.', '(i) 13 April 1919, Amritsar. (ii) Peaceful Baisakhi fair and protest against arrest of Dr. Saifuddin Kitchlew & Dr. Satyapal. (iii) General Reginald Dyer. (iv) Strikes, clashes with police, attacks on government buildings, followed by brutal martial law.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000019', 'Historically, Silk Routes connected Asia with:', '{"A":"Europe and Northern Africa","B":"Antarctica only","C":"Australia only","D":"South America only"}'::jsonb, 'A', 'MCQ', 'Social Science', 'The Making of a Global World', 1, 'Vibrant land & sea Silk Routes linked China, India, West Asia, Europe, and North Africa.', NULL, NULL, 'Vibrant land & sea Silk Routes linked China, India, West Asia, Europe, and North Africa.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001a', 'Which staple food was introduced to Europe and Asia from the Americas after Columbus''s voyages?', '{"A":"Rice","B":"Potato (along with maize, tomatoes, chillies)","C":"Wheat","D":"Barley"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Making of a Global World', 1, 'Potatoes transformed European peasant nutrition; Irish Potato Famine followed blight.', NULL, NULL, 'Potatoes transformed European peasant nutrition; Irish Potato Famine followed blight.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001b', 'The deadly cattle plague that devastated African livelihoods in the 1890s was:', '{"A":"Anthrax","B":"Rinderpest","C":"Smallpox","D":"Malaria"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Making of a Global World', 1, 'Rinderpest killed ~90% of cattle, forcing Africans into colonial wage labour.', NULL, NULL, 'Rinderpest killed ~90% of cattle, forcing Africans into colonial wage labour.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001c', 'Which biological weapon proved deadlier than guns during Spanish conquest of the Americas?', '{"A":"Plague","B":"Smallpox germs","C":"Cholera","D":"Typhoid"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Making of a Global World', 1, 'Indigenous populations lacked immunity against European smallpox.', NULL, NULL, 'Indigenous populations lacked immunity against European smallpox.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001d', 'Until the 18th century, the two richest centres of world trade were:', '{"A":"Britain and Germany","B":"India and China","C":"USA and Japan","D":"Spain and Portugal"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Making of a Global World', 1, 'India and China dominated pre-industrial Asian/world trade.', NULL, NULL, 'India and China dominated pre-industrial Asian/world trade.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001e', 'Assertion (A): The Irish Potato Famine of the 1840s caused massive starvation and emigration.
Reason (R): European peasants had grown overly dependent on a single crop, the potato, which was destroyed by fungal disease.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'The Making of a Global World', 1, 'Monoculture dependency amplified crop failure.', NULL, NULL, 'Monoculture dependency amplified crop failure.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000001f', 'Explain what "Silk Routes" signify beyond just Chinese silk trade.', NULL, NULL, 'VSA', 'Social Science', 'The Making of a Global World', 2, 'Silk Routes were vibrant pre-modern trade and cultural links carrying Chinese silk, Indian spices/textiles, European gold/silver, as well as Buddhism, Christianity, and Islam across continents.', 'Trade goods (1M) + Cultural/religious exchange (1M)', NULL, 'Silk Routes were vibrant pre-modern trade and cultural links carrying Chinese silk, Indian spices/textiles, European gold/silver, as well as Buddhism, Christianity, and Islam across continents.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000020', 'Give two examples of global food travels from America to Old World.', NULL, NULL, 'VSA', 'Social Science', 'The Making of a Global World', 2, 'Potatoes, soya, groundnuts, maize, tomatoes, chillies, and sweet potatoes came from American indigenous peoples after the 16th century.', 'Any two accurate crops + context (2M)', NULL, 'Potatoes, soya, groundnuts, maize, tomatoes, chillies, and sweet potatoes came from American indigenous peoples after the 16th century.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000021', 'How did the arrival of smallpox help Europeans conquer the Americas faster than military firepower?', NULL, NULL, 'SA', 'Social Science', 'The Making of a Global World', 3, 'Long isolation left Native Americans with zero acquired immunity against Old World germs. Smallpox spread rapidly ahead of Spanish conquistadors, decimating entire indigenous communities and clearing resistance.', 'Zero immunity (1.5M) + Rapid demographic collapse (1.5M)', NULL, 'Long isolation left Native Americans with zero acquired immunity against Old World germs. Smallpox spread rapidly ahead of Spanish conquistadors, decimating entire indigenous communities and clearing resistance.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000022', 'Why did thousands of Europeans flee to America in the 19th century?', NULL, NULL, 'SA', 'Social Science', 'The Making of a Global World', 3, 'Poverty, hunger, crowded overcrowded cities, deadly infectious diseases, religious dissenters being persecuted, and crop failures drove millions of Europeans toward the Americas.', '3 valid historical reasons × 1M', NULL, 'Poverty, hunger, crowded overcrowded cities, deadly infectious diseases, religious dissenters being persecuted, and crop failures drove millions of Europeans toward the Americas.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000023', 'Describe how trade, conquest, and cultural exchange worked together in the pre-modern world from Indus Valley links to the 16th-century Columbian exchange.', NULL, NULL, 'LA', 'Social Science', 'The Making of a Global World', 5, 'Indus coastal trade with West Asia (3000 BCE), Maldives cowries reaching China and East Africa, Silk Routes carrying silk, pottery, Indian cotton and world religions, Arab pasta/spaghetti cultural diffusion, and post-1500s American silver mines (Peru/Mexico) financing European-Asian trade alongside smallpox reshaping the Americas.', 'Pre-modern links (2M) + Silk Routes & culture (1.5M) + 16th century shift (1.5M)', NULL, 'Indus coastal trade with West Asia (3000 BCE), Maldives cowries reaching China and East Africa, Silk Routes carrying silk, pottery, Indian cotton and world religions, Arab pasta/spaghetti cultural diffusion, and post-1500s American silver mines (Peru/Mexico) financing European-Asian trade alongside smallpox reshaping the Americas.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000024', '(i) Why did Europeans eye Africa in the late 19th century? (ii) Why were Africans reluctant to work for wages initially? (iii) How did rinderpest reach Africa? (iv) What percentage of African cattle perished?', NULL, NULL, 'CASE', 'Social Science', 'The Making of a Global World', 4, '(i) Vast land and mineral resources. (ii) Abundant land and livestock sustained self-sufficient livelihoods with little need for wage labour. (iii) Infected cattle imported from British Asia to feed Italian soldiers in Eritrea. (iv) Nearly 90% of cattle.', '4 × 1M = 4M', 'In the 1880s Africa had plentiful land, small populations, and thriving pastoral wealth, leaving colonial mine and plantation owners desperate for wage labour until a cattle disease struck.', '(i) Vast land and mineral resources. (ii) Abundant land and livestock sustained self-sufficient livelihoods with little need for wage labour. (iii) Infected cattle imported from British Asia to feed Italian soldiers in Eritrea. (iv) Nearly 90% of cattle.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000025', 'The oldest surviving Japanese printed book (AD 868) containing six sheets of text and woodcut illustrations is:', '{"A":"Gita Govinda","B":"Diamond Sutra","C":"Ukiyo-e","D":"Tripitaka Koreana"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Print Culture and the Modern World', 1, 'Buddhist Diamond Sutra was printed in 868 CE.', NULL, NULL, 'Buddhist Diamond Sutra was printed in 868 CE.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000026', 'Who invented the first mechanical movable-type printing press in Europe (Strasbourg/Mainz)?', '{"A":"Marco Polo","B":"Johann Gutenberg","C":"Martin Luther","D":"James Watt"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Print Culture and the Modern World', 1, 'Gutenberg perfected the olive-press based printing press (~1448), printing the Bible.', NULL, NULL, 'Gutenberg perfected the olive-press based printing press (~1448), printing the Bible.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000027', 'Martin Luther''s Ninety-Five Theses (1517) sparked which major religious movement?', '{"A":"Counter-Reformation","B":"Protestant Reformation","C":"Enlightenment","D":"Industrial Revolution"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Print Culture and the Modern World', 1, 'Luther hailed printing as "the ultimate gift of God".', NULL, NULL, 'Luther hailed printing as "the ultimate gift of God".', 'EASY', true),
        ('10031111-0000-4000-8000-000000000028', 'Who wrote "Gulamgiri" (1871) exposing injustices of the caste system?', '{"A":"B.R. Ambedkar","B":"Jyotiba Phule","C":"E.V. Ramaswamy Periyar","D":"Kashibaba"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Print Culture and the Modern World', 1, 'Mahatma Jyotiba Phule dedicated Gulamgiri to anti-slavery fighters.', NULL, NULL, 'Mahatma Jyotiba Phule dedicated Gulamgiri to anti-slavery fighters.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000029', 'The Vernacular Press Act (1878) in British India was modelled on:', '{"A":"French press laws","B":"Irish Press Laws allowing censorship of seditious reports","C":"American First Amendment","D":"Russian Tsar decrees"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Print Culture and the Modern World', 1, 'Gave colonial government extensive rights to censor vernacular newspapers and seize presses.', NULL, NULL, 'Gave colonial government extensive rights to censor vernacular newspapers and seize presses.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000002a', 'Assertion (A): Catholic Church began maintaining an Index of Prohibited Books from 1558.
Reason (R): Individual printed interpretations of faith like Menocchio''s questioned Church authority and sparked fear of rebellious ideas.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Print Culture and the Modern World', 1, 'Print democratised dissent, prompting Church censorship.', NULL, NULL, 'Print democratised dissent, prompting Church censorship.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000002b', 'How did Marco Polo contribute to early print technology in Europe?', NULL, NULL, 'VSA', 'Social Science', 'Print Culture and the Modern World', 2, 'In 1295 Marco Polo returned to Italy after years in China and brought back the knowledge of Chinese woodblock printing, soon adopted across Italy and Europe.', '1295 return from China (1M) + Woodblock spread (1M)', NULL, 'In 1295 Marco Polo returned to Italy after years in China and brought back the knowledge of Chinese woodblock printing, soon adopted across Italy and Europe.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000002c', 'What were "penny chapbooks" in England and "Bibliotheque Bleue" in France?', NULL, NULL, 'VSA', 'Social Science', 'Print Culture and the Modern World', 2, 'Low-priced small pocket-sized books sold by pedlars (chapmen) in England for a penny, and blue-cover cheap books in France aimed at poor readers.', '1M each', NULL, 'Low-priced small pocket-sized books sold by pedlars (chapmen) in England for a penny, and blue-cover cheap books in France aimed at poor readers.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000002d', 'Explain how print culture assisted the growth of nationalism in India despite colonial censorship.', NULL, NULL, 'SA', 'Social Science', 'Print Culture and the Modern World', 3, 'Nationalist newspapers (Kesari, Amrita Bazar Patrika, Bengalee) reported colonial misrule, united people across regions, mobilised protests against Partition/Rowlatt Act, and kept circulating despite the Vernacular Press Act of 1878.', '3 clear mechanisms × 1M', NULL, 'Nationalist newspapers (Kesari, Amrita Bazar Patrika, Bengalee) reported colonial misrule, united people across regions, mobilised protests against Partition/Rowlatt Act, and kept circulating despite the Vernacular Press Act of 1878.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000002e', 'How did print empower Indian women readers and writers in the 19th century? Give two examples.', NULL, NULL, 'SA', 'Social Science', 'Print Culture and the Modern World', 3, 'Liberal families educated women at home; Rashsundari Debi wrote the first full Bengali autobiography Amar Jiban (1876); Tarabai Shinde and Pandita Ramabai wrote passionately about upper-caste widows'' hardships.', 'Social impact (1M) + Two writers (2M)', NULL, 'Liberal families educated women at home; Rashsundari Debi wrote the first full Bengali autobiography Amar Jiban (1876); Tarabai Shinde and Pandita Ramabai wrote passionately about upper-caste widows'' hardships.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000002f', 'Examine the impact of the Print Revolution in 16th-century Europe across reading publics, religious reform (Martin Luther), and fear of print (Erasmus / Index of Prohibited Books).', NULL, NULL, 'LA', 'Social Science', 'Print Culture and the Modern World', 5, 'Created a new reading public merging oral folk culture with printed ballads; lowered book costs; enabled Martin Luther''s 95 Theses to sell 5,000 copies within weeks sparking Protestant Reformation; alarmed conservatives (Catholic Index 1558, execution of Menocchio) fearing seditious irreligious ideas.', 'Reading public (1.5M) + Religious debate & Luther (2M) + Censorship fears (1.5M)', NULL, 'Created a new reading public merging oral folk culture with printed ballads; lowered book costs; enabled Martin Luther''s 95 Theses to sell 5,000 copies within weeks sparking Protestant Reformation; alarmed conservatives (Catholic Index 1558, execution of Menocchio) fearing seditious irreligious ideas.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000030', '(i) Who founded Bengal Gazette in 1780? (ii) Why did Governor-General Warren Hastings persecute the editor? (iii) How did Ram Mohan Roy counter orthodox newspapers like Samachar Chandrika? (iv) Name one early Tamil or Persian newspaper.', NULL, NULL, 'CASE', 'Social Science', 'Print Culture and the Modern World', 4, '(i) James Augustus Hickey. (ii) He published sharp gossip about Company senior officials'' corruption. (iii) Published Sambad Kaumudi (1821) advocating social reforms. (iv) Jam-i-Jahan Nama / Shamsul Akhbar (Persian, 1822) or Bombay Samachar.', '4 × 1M = 4M', 'Private English printing in Calcutta began as a weekly commercial paper open to all but influenced by none, soon sparking intense debate between colonial administrators, social reformers, and orthodox groups.', '(i) James Augustus Hickey. (ii) He published sharp gossip about Company senior officials'' corruption. (iii) Published Sambad Kaumudi (1821) advocating social reforms. (iv) Jam-i-Jahan Nama / Shamsul Akhbar (Persian, 1822) or Bombay Samachar.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000031', 'Black cotton soil of the Deccan trap region is also called:', '{"A":"Khadar","B":"Regur soil","C":"Laterite soil","D":"Bhangar"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Resources and Development', 1, 'Black/Regur soil retains moisture well and cracks in hot weather.', NULL, NULL, 'Black/Regur soil retains moisture well and cracks in hot weather.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000032', 'Rio de Janeiro Earth Summit (1992) adopted which declaration for sustainable development?', '{"A":"Agenda 21","B":"Kyoto Protocol","C":"Montreal Protocol","D":"Paris Accord"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Resources and Development', 1, 'Agenda 21 targets global sustainable development.', NULL, NULL, 'Agenda 21 targets global sustainable development.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000033', 'Laterite soil is typically suitable for growing:', '{"A":"Cotton","B":"Tea, coffee, and cashew nuts (after soil conservation)","C":"Sugarcane in deserts","D":"Jute only"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Resources and Development', 1, 'Acidic leached laterite in Karnataka/Kerala/TN supports tea, coffee, and red laterite supports cashew.', NULL, NULL, 'Acidic leached laterite in Karnataka/Kerala/TN supports tea, coffee, and red laterite supports cashew.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000034', 'Which is the oldest alluvial soil found away from floodplains containing calcareous kankar nodules?', '{"A":"Khadar","B":"Bangar","C":"Regur","D":"Peat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Resources and Development', 1, 'Bangar is old alluvium; Khadar is fertile new alluvium.', NULL, NULL, 'Bangar is old alluvium; Khadar is fertile new alluvium.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000035', 'Net Sown Area percentage is highest in which two Indian states?', '{"A":"Arunachal Pradesh and Mizoram","B":"Punjab and Haryana (>80%)","C":"Jharkhand and Odisha","D":"Kerala and Goa"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Resources and Development', 1, 'Punjab and Haryana have over 80% Net Sown Area.', NULL, NULL, 'Punjab and Haryana have over 80% Net Sown Area.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000036', 'Assertion (A): Resource planning is essential for sustainable existence of all forms of life.
Reason (R): Indiscriminate exploitation has caused resource depletion, ecological crises like global warming, and unequal wealth divide.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Resources and Development', 1, 'Equitable planned use prevents ecological collapse.', NULL, NULL, 'Equitable planned use prevents ecological collapse.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000037', 'What is sustainable development? State one goal of Agenda 21.', NULL, NULL, 'VSA', 'Social Science', 'Resources and Development', 2, 'Development that meets present needs without compromising the ability of future generations or damaging the environment. Agenda 21 promotes combating environmental damage, poverty, and disease through global cooperation.', '1M each', NULL, 'Development that meets present needs without compromising the ability of future generations or damaging the environment. Agenda 21 promotes combating environmental damage, poverty, and disease through global cooperation.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000038', 'Distinguish between Bangar and Khadar alluvial soils (two points).', NULL, NULL, 'VSA', 'Social Science', 'Resources and Development', 2, 'Bangar: old alluvium, higher concentration of kankar nodules, less fertile. Khadar: new alluvium renewed annually by floods, finer particles, much more fertile.', '2 points × 1M', NULL, 'Bangar: old alluvium, higher concentration of kankar nodules, less fertile. Khadar: new alluvium renewed annually by floods, finer particles, much more fertile.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000039', 'Explain three steps involved in Resource Planning in India.', NULL, NULL, 'SA', 'Social Science', 'Resources and Development', 3, '(1) Identification and inventory of resources across regions via surveying, mapping, and measurement. (2) Evolving a planning structure endowed with appropriate technology, skill, and institutional setup. (3) Matching resource development plans with overall national development plans.', '1M per step', NULL, '(1) Identification and inventory of resources across regions via surveying, mapping, and measurement. (2) Evolving a planning structure endowed with appropriate technology, skill, and institutional setup. (3) Matching resource development plans with overall national development plans.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000003a', 'Describe three human causes of land degradation in different states of India.', NULL, NULL, 'SA', 'Social Science', 'Resources and Development', 3, 'Mining & quarrying (Jharkhand, Chhattisgarh, Odisha leaving deep scars), overgrazing (Gujarat, Rajasthan, MP), and over-irrigation causing waterlogging & salinity (Punjab, Haryana, Western UP).', '3 states & causes × 1M', NULL, 'Mining & quarrying (Jharkhand, Chhattisgarh, Odisha leaving deep scars), overgrazing (Gujarat, Rajasthan, MP), and over-irrigation causing waterlogging & salinity (Punjab, Haryana, Western UP).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000003b', 'Describe the characteristics, mineral richness, and regional distribution of Black Soil and Alluvial Soil in India, and list three soil conservation methods against erosion.', NULL, NULL, 'LA', 'Social Science', 'Resources and Development', 5, 'Alluvial (northern plains, deltas; potash/lime rich; wheat/rice/sugarcane); Black/Regur (Maharashtra, Malwa, MP; clayey moisture-retentive; CaCO₃, Mg, potash; cotton). Conservation: contour ploughing, terrace farming, strip cropping, shelter belts.', 'Two soils (3M) + Conservation methods (2M)', NULL, 'Alluvial (northern plains, deltas; potash/lime rich; wheat/rice/sugarcane); Black/Regur (Maharashtra, Malwa, MP; clayey moisture-retentive; CaCO₃, Mg, potash; cotton). Conservation: contour ploughing, terrace farming, strip cropping, shelter belts.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000003c', '(i) Define gully erosion. (ii) What are gullies called in the Chambal basin? (iii) How does wind cause sheet/wind erosion? (iv) Suggest one hilly-slope soil conservation technique.', NULL, NULL, 'CASE', 'Social Science', 'Resources and Development', 4, '(i) Running water cuts deep channels through clayey soil making land unfit for cultivation. (ii) Badlands / Ravines. (iii) Wind blows loose topsoil off flat or sloping land. (iv) Terrace cultivation or contour ploughing.', '4 × 1M = 4M', 'Unchecked deforestation, steep slope ploughing, and heavy monsoon run-off strip fertile topsoil across western and central Indian river basins, carving deep unusable channels.', '(i) Running water cuts deep channels through clayey soil making land unfit for cultivation. (ii) Badlands / Ravines. (iii) Wind blows loose topsoil off flat or sloping land. (iv) Terrace cultivation or contour ploughing.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000003d', 'Project Tiger was launched in India in the year:', '{"A":"1968","B":"1973","C":"1980","D":"1992"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Forest and Wildlife Resources', 1, 'Project Tiger began in 1973 after steep tiger population decline.', NULL, NULL, 'Project Tiger began in 1973 after steep tiger population decline.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000003e', 'Which category of forests enjoys the highest legal protection against poaching and grazing in India?', '{"A":"Protected Forests","B":"Reserved Forests","C":"Unclassed Forests","D":"Private Groves"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Forest and Wildlife Resources', 1, 'Over half of total forest land is Reserved Forest (most valuable for conservation).', NULL, NULL, 'Over half of total forest land is Reserved Forest (most valuable for conservation).', 'EASY', true),
        ('10031111-0000-4000-8000-00000000003f', 'Sariska Tiger Reserve where villagers fought against mining using the Wildlife Protection Act is in:', '{"A":"Madhya Pradesh","B":"Rajasthan","C":"Uttarakhand","D":"Assam"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Forest and Wildlife Resources', 1, 'Sariska is located in Alwar district, Rajasthan.', NULL, NULL, 'Sariska is located in Alwar district, Rajasthan.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000040', 'Joint Forest Management (JFM) was first formally adopted in 1988 by which Indian state?', '{"A":"Kerala","B":"Odisha","C":"Himachal Pradesh","D":"Gujarat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Forest and Wildlife Resources', 1, 'Odisha passed the first JFM resolution in 1988.', NULL, NULL, 'Odisha passed the first JFM resolution in 1988.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000041', 'Beej Bachao Andolan conserving traditional crop varieties began in:', '{"A":"Tehri and Navdanya (Uttarakhand)","B":"Bastar","C":"Sundarbans","D":"Nilgiris"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Forest and Wildlife Resources', 1, 'Farmers in Tehri demonstrated organic diversified crop cultivation without synthetic chemicals.', NULL, NULL, 'Farmers in Tehri demonstrated organic diversified crop cultivation without synthetic chemicals.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000042', 'Assertion (A): Sacred groves across India have preserved patches of virgin forest untouched for centuries.
Reason (R): Local communities revere specific trees like mahua, kadamba, peepal, and banyan as sacred dwellings of spirits or deities.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Forest and Wildlife Resources', 1, 'Cultural reverence protected rich biodiversity.', NULL, NULL, 'Cultural reverence protected rich biodiversity.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000043', 'What is Joint Forest Management (JFM)? State its main objective.', NULL, NULL, 'VSA', 'Social Science', 'Forest and Wildlife Resources', 2, 'A partnership programme (started 1988 in Odisha) involving local village institutions in protecting and managing degraded forest land in return for non-timber forest produce and a share in harvested timber.', 'Definition (1M) + Benefit-sharing objective (1M)', NULL, 'A partnership programme (started 1988 in Odisha) involving local village institutions in protecting and managing degraded forest land in return for non-timber forest produce and a share in harvested timber.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000044', 'Distinguish between Reserved Forests and Protected Forests.', NULL, NULL, 'VSA', 'Social Science', 'Forest and Wildlife Resources', 2, 'Reserved Forests (>50% of forest area) have strict restrictions and highest conservation value; Protected Forests (~1/3rd) are safeguarded from further depletion with limited regulated local access.', '1M each', NULL, 'Reserved Forests (>50% of forest area) have strict restrictions and highest conservation value; Protected Forests (~1/3rd) are safeguarded from further depletion with limited regulated local access.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000045', 'Describe how Indian communities themselves have conserved forests and wildlife (give three examples).', NULL, NULL, 'SA', 'Social Science', 'Forest and Wildlife Resources', 3, '(1) Chipko Movement in Himalayas resisted deforestation via community afforestation. (2) Alwar (Rajasthan) villagers declared 1,200 hectares Bhairodev Dakav Sonchuri banning hunting. (3) Bishnois of Rajasthan protect blackbuck, nilgai, and khejri trees; Sacred groves protect tamarind/mango/mahua.', '3 examples × 1M', NULL, '(1) Chipko Movement in Himalayas resisted deforestation via community afforestation. (2) Alwar (Rajasthan) villagers declared 1,200 hectares Bhairodev Dakav Sonchuri banning hunting. (3) Bishnois of Rajasthan protect blackbuck, nilgai, and khejri trees; Sacred groves protect tamarind/mango/mahua.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000046', 'State three major provisions of the Indian Wildlife (Protection) Act, 1972.', NULL, NULL, 'SA', 'Social Science', 'Forest and Wildlife Resources', 3, '(1) All-India list of protected species banning hunting. (2) Legal protection to habitats and strict restrictions on wildlife trade. (3) Establishment of National Parks and Wildlife Sanctuaries by Central/State governments.', '3 × 1M', NULL, '(1) All-India list of protected species banning hunting. (2) Legal protection to habitats and strict restrictions on wildlife trade. (3) Establishment of National Parks and Wildlife Sanctuaries by Central/State governments.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000047', 'Why do we need to conserve our forests and wildlife? Classify forests in India into three administrative categories and mention states where Reserved and Unclassed forests dominate.', NULL, NULL, 'LA', 'Social Science', 'Forest and Wildlife Resources', 5, 'Conservation preserves ecological diversity and life-support systems (water, air, soil) plus genetic stock for crops/medicines. Categories: Reserved (J&K, Andhra Pradesh, Uttarakhand, Kerala, TN, WB, Maharashtra), Protected (Bihar, Haryana, Punjab, HP, Odisha, Rajasthan), Unclassed (all North-Eastern states and parts of Gujarat managed by local communities).', 'Need (2M) + 3 categories & states (3M)', NULL, 'Conservation preserves ecological diversity and life-support systems (water, air, soil) plus genetic stock for crops/medicines. Categories: Reserved (J&K, Andhra Pradesh, Uttarakhand, Kerala, TN, WB, Maharashtra), Protected (Bihar, Haryana, Punjab, HP, Odisha, Rajasthan), Unclassed (all North-Eastern states and parts of Gujarat managed by local communities).', 'HARD', true),
        ('10031111-0000-4000-8000-000000000048', '(i) Name two sacred trees worshipped by Munda and Santhal tribes of Chota Nagpur. (ii) Which fruit trees are worshipped during weddings in Odisha and Bihar? (iii) How do Bishnoi villages in Rajasthan show wildlife coexistence? (iv) Name one tiger reserve in Uttarakhand.', NULL, NULL, 'CASE', 'Social Science', 'Forest and Wildlife Resources', 4, '(i) Mahua and Kadamba. (ii) Tamarind and Mango. (iii) Blackbuck, chinkara, nilgai, and peacocks roam freely around villages protected from harm. (iv) Corbett National Park.', '4 × 1M = 4M', 'Nature worship is an age-old tribal belief across India based on the premise that all creations of nature must be protected, leaving patches of pristine sacred groves untouched.', '(i) Mahua and Kadamba. (ii) Tamarind and Mango. (iii) Blackbuck, chinkara, nilgai, and peacocks roam freely around villages protected from harm. (iv) Corbett National Park.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000049', 'Which multipurpose river valley project was called "Temples of Modern India" by Jawaharlal Nehru?', '{"A":"Tehri","B":"Bhakra Nangal (and modern dams)","C":"Sardar Sarovar","D":"Koyna"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Water Resources', 1, 'Nehru proclaimed multipurpose dams as temples integrating agricultural and industrial growth.', NULL, NULL, 'Nehru proclaimed multipurpose dams as temples integrating agricultural and industrial growth.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004a', 'Bamboo drip irrigation system (200-year-old method) is practised in:', '{"A":"Rajasthan","B":"Meghalaya","C":"Tamil Nadu","D":"Punjab"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Water Resources', 1, 'Meghalaya channels hill stream water to black pepper/betel via bamboo pipes.', NULL, NULL, 'Meghalaya channels hill stream water to black pepper/betel via bamboo pipes.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004b', 'In Western Rajasthan, underground tanks built inside homes to store rainwater are called:', '{"A":"Kuls","B":"Tankas","C":"Johads","D":"Khadins"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Water Resources', 1, 'Tankas store "palar pani" (purest rainwater) and cool underground rooms.', NULL, NULL, 'Tankas store "palar pani" (purest rainwater) and cool underground rooms.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004c', 'Hirakud Dam is constructed across which river?', '{"A":"Satluj","B":"Mahanadi","C":"Narmada","D":"Krishna"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Water Resources', 1, 'Hirakud (Odisha) is on the Mahanadi River.', NULL, NULL, 'Hirakud (Odisha) is on the Mahanadi River.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004d', 'Which Indian state made rooftop rainwater harvesting compulsory for every house by law?', '{"A":"Kerala","B":"Tamil Nadu","C":"Karnataka","D":"Gujarat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Water Resources', 1, 'Tamil Nadu was the first state to mandate rooftop rainwater harvesting.', NULL, NULL, 'Tamil Nadu was the first state to mandate rooftop rainwater harvesting.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004e', 'Assertion (A): Multi-purpose dams have faced intense opposition and social movements like Narmada Bachao Andolan.
Reason (R): Large reservoirs submerge fertile fields, forests, and displace local tribal communities without adequate rehabilitation.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Water Resources', 1, 'Displacement and ecological loss drive anti-dam protests.', NULL, NULL, 'Displacement and ecological loss drive anti-dam protests.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000004f', 'What is rainwater harvesting? Why is rainwater called "palar pani" in Rajasthan?', NULL, NULL, 'VSA', 'Social Science', 'Water Resources', 2, 'Collecting and storing rainwater for direct reuse or groundwater recharge. In arid Bikaner/Phalodi, stored rainwater is called "palar pani" and prized as the purest form of natural drinking water.', '1M each', NULL, 'Collecting and storing rainwater for direct reuse or groundwater recharge. In arid Bikaner/Phalodi, stored rainwater is called "palar pani" and prized as the purest form of natural drinking water.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000050', 'Name the rivers on which (i) Bhakra Nangal Dam and (ii) Sardar Sarovar Dam are built.', NULL, NULL, 'VSA', 'Social Science', 'Water Resources', 2, '(i) Satluj river; (ii) Narmada river.', '1M each', NULL, '(i) Satluj river; (ii) Narmada river.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000051', 'Give three causes of water scarcity in regions that receive ample annual rainfall.', NULL, NULL, 'SA', 'Social Science', 'Water Resources', 3, '(1) Over-exploitation and excessive pumping for growing population and irrigation. (2) Unequal access across social groups. (3) Water pollution from domestic sewage, industrial effluents, and agro-chemicals rendering water hazardous.', '3 × 1M', NULL, '(1) Over-exploitation and excessive pumping for growing population and irrigation. (2) Unequal access across social groups. (3) Water pollution from domestic sewage, industrial effluents, and agro-chemicals rendering water hazardous.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000052', 'Describe any three traditional rainwater harvesting systems practised across different regions of India.', NULL, NULL, 'SA', 'Social Science', 'Water Resources', 3, '(1) Guls or Kuls (diversion channels in Western Himalayas for agriculture). (2) Khadins (Jaisalmer) and Johads (Rajasthan) rain-fed storage fields. (3) Inundation channels in Bengal floodplains and Bamboo drip irrigation in Meghalaya.', '3 distinct systems × 1M', NULL, '(1) Guls or Kuls (diversion channels in Western Himalayas for agriculture). (2) Khadins (Jaisalmer) and Johads (Rajasthan) rain-fed storage fields. (3) Inundation channels in Bengal floodplains and Bamboo drip irrigation in Meghalaya.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000053', 'Evaluate the advantages and disadvantages of multi-purpose river projects in India (5 points total). Why has excessive irrigation in dry areas triggered ecological problems?', NULL, NULL, 'LA', 'Social Science', 'Water Resources', 5, 'Advantages: irrigation, hydroelectricity, flood control, inland navigation/fisheries. Disadvantages: fragmented river flow & poor sediment downstream (silting habitats), submergence of forests/soils, displacement of tribals (Narmada Bachao / Tehri), inter-state water disputes (Krishna-Godavari), even triggering floods during heavy rain release. Irrigation shifts cropping patterns toward water-intensive crops causing soil salinisation.', '3M advantages/disadvantages + 2M ecological & social critique', NULL, 'Advantages: irrigation, hydroelectricity, flood control, inland navigation/fisheries. Disadvantages: fragmented river flow & poor sediment downstream (silting habitats), submergence of forests/soils, displacement of tribals (Narmada Bachao / Tehri), inter-state water disputes (Krishna-Godavari), even triggering floods during heavy rain release. Irrigation shifts cropping patterns toward water-intensive crops causing soil salinisation.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000054', '(i) Explain how rooftop rainwater harvesting recharges borewells/handpumps in cities. (ii) Which village in Mysuru (Karnataka) achieved near-total household rainwater sufficiency? (iii) Approximately how many litres can Gendathur harvest annually? (iv) Name one city-friendly rain conservation step.', NULL, NULL, 'CASE', 'Social Science', 'Water Resources', 4, '(i) PVC pipe filters rooftop water down into an underground sump or abandoned well to percolate into aquifers. (ii) Gendathur. (iii) ~1,00,000 litres per house (total ~1 crore litres across 200 homes). (iv) Permeable pavements or mandatory rooftop pits.', '4 × 1M = 4M', 'In Gendathur, a remote backward village in Mysuru, Karnataka, nearly 200 households have installed rooftop rainwater harvesting systems tapping an average 1,000 mm annual rainfall at 80% collection efficiency.', '(i) PVC pipe filters rooftop water down into an underground sump or abandoned well to percolate into aquifers. (ii) Gendathur. (iii) ~1,00,000 litres per house (total ~1 crore litres across 200 homes). (iv) Permeable pavements or mandatory rooftop pits.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000055', '"Slash and burn" shifting cultivation in North-Eastern India is locally known as:', '{"A":"Milpa","B":"Jhumming","C":"Bewar","D":"Podu"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Agriculture', 1, 'Jhumming in Assam, Meghalaya, Mizoram, Nagaland.', NULL, NULL, 'Jhumming in Assam, Meghalaya, Mizoram, Nagaland.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000056', 'Which is a Rabi crop sown in winter (Oct–Dec) and harvested in summer (Apr–Jun)?', '{"A":"Paddy","B":"Wheat (and Mustard, Gram, Peas)","C":"Jowar","D":"Cotton"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Agriculture', 1, 'Wheat, barley, peas, gram, mustard are Rabi crops.', NULL, NULL, 'Wheat, barley, peas, gram, mustard are Rabi crops.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000057', 'Golden Fibre of India requiring high temperature and well-drained fertile floodplains is:', '{"A":"Cotton","B":"Jute","C":"Silk","D":"Hemp"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Agriculture', 1, 'Jute (West Bengal, Bihar, Assam) is called Golden Fibre.', NULL, NULL, 'Jute (West Bengal, Bihar, Assam) is called Golden Fibre.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000058', 'Which pulse crop is leguminous EXCEPT it does NOT fix atmospheric nitrogen effectively?', '{"A":"Gram","B":"Arhar (Tur)","C":"Moong","D":"Urad"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Agriculture', 1, 'Arhar does not restore soil nitrogen like other pulses.', NULL, NULL, 'Arhar does not restore soil nitrogen like other pulses.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000059', 'Arabica variety of coffee cultivated in Karnataka''s Baba Budan Hills was originally brought from:', '{"A":"Brazil","B":"Yemen","C":"Ethiopia","D":"Colombia"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Agriculture', 1, 'Indian Arabica originated from Yemen.', NULL, NULL, 'Indian Arabica originated from Yemen.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000005a', 'Assertion (A): Intensive subsistence farming puts heavy pressure on agricultural land in India.
Reason (R): The right of inheritance dividing land across generations renders landholdings tiny and uneconomical.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Agriculture', 1, 'Fragmentation forces maximum output from tiny plots.', NULL, NULL, 'Fragmentation forces maximum output from tiny plots.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000005b', 'Distinguish between Kharif and Zaid cropping seasons with two examples each.', NULL, NULL, 'VSA', 'Social Science', 'Agriculture', 2, 'Kharif (onset of monsoon Jun–Oct: rice, maize, cotton, groundnut). Zaid (short summer Mar–Jun between Rabi and Kharif: watermelon, muskmelon, cucumber, fodder).', '1M each', NULL, 'Kharif (onset of monsoon Jun–Oct: rice, maize, cotton, groundnut). Zaid (short summer Mar–Jun between Rabi and Kharif: watermelon, muskmelon, cucumber, fodder).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000005c', 'Mention the geographical temperature and rainfall conditions required for Rice cultivation.', NULL, NULL, 'VSA', 'Social Science', 'Agriculture', 2, 'High temperature (>25°C), high humidity, and annual rainfall >100 cm (or assured canal/tubewell irrigation in Punjab/Haryana).', 'Temperature (1M) + Rainfall/irrigation (1M)', NULL, 'High temperature (>25°C), high humidity, and annual rainfall >100 cm (or assured canal/tubewell irrigation in Punjab/Haryana).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000005d', 'Compare Primitive Subsistence Farming and Commercial Farming on three parameters.', NULL, NULL, 'SA', 'Social Science', 'Agriculture', 3, '(1) Land size: tiny patches vs large tracts/plantations. (2) Tools & inputs: hoe/dao/family labour & monsoon dependence vs HYV seeds, chemical fertilisers, pesticides, machinery. (3) Purpose: self-consumption vs market profit.', '3 × 1M', NULL, '(1) Land size: tiny patches vs large tracts/plantations. (2) Tools & inputs: hoe/dao/family labour & monsoon dependence vs HYV seeds, chemical fertilisers, pesticides, machinery. (3) Purpose: self-consumption vs market profit.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000005e', 'Explain three institutional and technological reforms introduced by Government of India after Independence to improve agriculture.', NULL, NULL, 'SA', 'Social Science', 'Agriculture', 3, 'Collectivisation & abolition of zamindari; Green Revolution & White Revolution (Operation Flood); Crop insurance against drought/flood, Kisan Credit Card (KCC), PAIS, Minimum Support Price (MSP).', '3 reforms × 1M', NULL, 'Collectivisation & abolition of zamindari; Green Revolution & White Revolution (Operation Flood); Crop insurance against drought/flood, Kisan Credit Card (KCC), PAIS, Minimum Support Price (MSP).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000005f', 'Describe the climatic requirements and major producing states for (a) Wheat and (b) Sugarcane. Also explain why Vinoba Bhave''s Bhoodan-Gramdan movement is called the "Bloodless Revolution".', NULL, NULL, 'LA', 'Social Science', 'Agriculture', 5, 'Wheat: cool growing season, bright sunshine at ripening, 50–75 cm rainfall; Ganga-Satluj plains & Deccan black soil (Punjab, Haryana, UP, MP, Bihar, Rajasthan). Sugarcane: hot & humid 21–27°C, 75–100 cm rainfall; UP, Maharashtra, Karnataka, TN, AP. Bhoodan-Gramdan: landowners voluntarily donated land/villages to landless without violence.', 'Wheat (1.5M) + Sugarcane (1.5M) + Bhoodan-Gramdan (2M)', NULL, 'Wheat: cool growing season, bright sunshine at ripening, 50–75 cm rainfall; Ganga-Satluj plains & Deccan black soil (Punjab, Haryana, UP, MP, Bihar, Rajasthan). Sugarcane: hot & humid 21–27°C, 75–100 cm rainfall; UP, Maharashtra, Karnataka, TN, AP. Bhoodan-Gramdan: landowners voluntarily donated land/villages to landless without violence.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000060', '(i) Why is Tea classified as a beverage plantation crop? (ii) Mention soil & slope needed for tea bushes. (iii) Why does tea processing happen inside the garden itself? (iv) Name two leading tea-producing Indian states.', NULL, NULL, 'CASE', 'Social Science', 'Agriculture', 4, '(i) Single cash crop grown on large estates for market/export using labour-intensive processing. (ii) Deep fertile well-drained soil rich in humus & organic matter on frost-free gentle hills. (iii) To preserve freshness of tender plucked leaves. (iv) Assam, West Bengal (Darjeeling/Jalpaiguri), Tamil Nadu, Kerala.', '4 × 1M = 4M', 'Tea bushes require warm, moist, frost-free tropical and sub-tropical climates with frequent evenly distributed showers year-round for continuous growth of tender leaves.', '(i) Single cash crop grown on large estates for market/export using labour-intensive processing. (ii) Deep fertile well-drained soil rich in humus & organic matter on frost-free gentle hills. (iii) To preserve freshness of tender plucked leaves. (iv) Assam, West Bengal (Darjeeling/Jalpaiguri), Tamil Nadu, Kerala.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000061', 'Highest quality hard coal with more than 80% carbon content is:', '{"A":"Lignite","B":"Bituminous","C":"Anthracite","D":"Peat"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Minerals and Energy Resources', 1, 'Anthracite is the highest grade hard coal.', NULL, NULL, 'Anthracite is the highest grade hard coal.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000062', 'Kudremukh mines in the Western Ghats of Karnataka are world-famous for:', '{"A":"Bauxite","B":"Iron ore","C":"Copper","D":"Mica"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Minerals and Energy Resources', 1, 'Kudremukh exports iron ore slurry via pipeline to Mangaluru port.', NULL, NULL, 'Kudremukh exports iron ore slurry via pipeline to Mangaluru port.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000063', 'Which mineral is the ore from which aluminium is extracted (found prominently in Odisha''s Panchpatmali)?', '{"A":"Magnetite","B":"Bauxite","C":"Galena","D":"Monazite"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Minerals and Energy Resources', 1, 'Odisha is India''s largest bauxite-producing state.', NULL, NULL, 'Odisha is India''s largest bauxite-producing state.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000064', 'Monazite sands of Kerala are rich in which nuclear energy mineral?', '{"A":"Uranium","B":"Thorium","C":"Plutonium","D":"Radium"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Minerals and Energy Resources', 1, 'Kerala monazite contains abundant Thorium.', NULL, NULL, 'Kerala monazite contains abundant Thorium.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000065', 'Which non-metallic mineral is indispensable in electrical and electronic industries due to its excellent di-electric strength and insulating properties?', '{"A":"Limestone","B":"Mica","C":"Gypsum","D":"Dolomite"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Minerals and Energy Resources', 1, 'Mica splits into thin sheets and resists high voltage (Koderma-Gaya-Hazaribagh belt).', NULL, NULL, 'Mica splits into thin sheets and resists high voltage (Koderma-Gaya-Hazaribagh belt).', 'EASY', true),
        ('10031111-0000-4000-8000-000000000066', 'Assertion (A): India needs to rapidly shift toward non-conventional energy sources like solar and wind energy.
Reason (R): Fossil fuels are finite, unevenly distributed, and raise serious environmental pollution concerns.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Minerals and Energy Resources', 1, 'Renewables ensure energy security and lower emissions.', NULL, NULL, 'Renewables ensure energy security and lower emissions.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000067', 'How do minerals occur in igneous and metamorphic rocks vs sedimentary rocks?', NULL, NULL, 'VSA', 'Social Science', 'Minerals and Energy Resources', 2, 'In igneous/metamorphic rocks, minerals occur in cracks, crevices, faults, and joints (smaller = veins, larger = lodes: tin, copper, zinc, lead). In sedimentary rocks, they occur in horizontal beds/layers via deposition and accumulation (coal, iron ore, gypsum).', '1M each', NULL, 'In igneous/metamorphic rocks, minerals occur in cracks, crevices, faults, and joints (smaller = veins, larger = lodes: tin, copper, zinc, lead). In sedimentary rocks, they occur in horizontal beds/layers via deposition and accumulation (coal, iron ore, gypsum).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000068', 'Why is Natural Gas considered an environment-friendly fuel?', NULL, NULL, 'VSA', 'Social Science', 'Minerals and Energy Resources', 2, 'It has low carbon dioxide emissions compared to coal and oil, burns cleanly without leaving ash, and powers CNG vehicles and fertiliser plants efficiently.', 'Low CO₂ emissions (1M) + Clean fuel/CNG use (1M)', NULL, 'It has low carbon dioxide emissions compared to coal and oil, burns cleanly without leaving ash, and powers CNG vehicles and fertiliser plants efficiently.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000069', 'Why is conservation of mineral resources urgent? State three practical methods to conserve minerals.', NULL, NULL, 'SA', 'Social Science', 'Minerals and Energy Resources', 3, 'Minerals take millions of years to form and represent <1% of Earth''s crust; rapid extraction raises costs and lowers grade. Methods: planned sustainable use, improved technologies for low-grade ores, recycling scrap metals and using substitutes.', 'Urgency (1.5M) + 3 methods (1.5M)', NULL, 'Minerals take millions of years to form and represent <1% of Earth''s crust; rapid extraction raises costs and lowers grade. Methods: planned sustainable use, improved technologies for low-grade ores, recycling scrap metals and using substitutes.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000006a', 'Describe the four major iron ore belts in India.', NULL, NULL, 'SA', 'Social Science', 'Minerals and Energy Resources', 3, 'Odisha-Jharkhand belt (Badampahar, Gua, Noamundi); Durg-Bastar-Chandrapur belt (Bailadila hills -> Visakhapatnam); Ballari-Chitradurga-Chikkamagaluru-Tumakuru belt (Kudremukh); Maharashtra-Goa belt (Ratnagiri, Marmagao).', 'Any 3–4 belts clearly named (3M)', NULL, 'Odisha-Jharkhand belt (Badampahar, Gua, Noamundi); Durg-Bastar-Chandrapur belt (Bailadila hills -> Visakhapatnam); Ballari-Chitradurga-Chikkamagaluru-Tumakuru belt (Kudremukh); Maharashtra-Goa belt (Ratnagiri, Marmagao).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000006b', 'Distinguish between Conventional and Non-Conventional sources of energy. Explain India''s potential in Solar, Wind, and Biogas (Gobar gas) energy in rural and arid regions.', NULL, NULL, 'LA', 'Social Science', 'Minerals and Energy Resources', 5, 'Conventional: coal, petroleum, natural gas, hydel/thermal (exhaustible except hydel, mostly polluting). Non-conventional: solar, wind, tidal, geothermal, biogas (renewable, eco-friendly). Solar (tropical India, Rajasthan/Gujarat photovoltaic parks), Wind (Nagercoil to Madurai in TN, AP, Karnataka, Gujarat), Biogas (decomposing farm/cattle waste provides clean fuel + enriched organic manure).', 'Distinction (2M) + 3 renewable potentials (3M)', NULL, 'Conventional: coal, petroleum, natural gas, hydel/thermal (exhaustible except hydel, mostly polluting). Non-conventional: solar, wind, tidal, geothermal, biogas (renewable, eco-friendly). Solar (tropical India, Rajasthan/Gujarat photovoltaic parks), Wind (Nagercoil to Madurai in TN, AP, Karnataka, Gujarat), Biogas (decomposing farm/cattle waste provides clean fuel + enriched organic manure).', 'HARD', true),
        ('10031111-0000-4000-8000-00000000006c', '(i) Identify the hazards faced by miners due to noxious fumes and roof collapses. (ii) Which lung disease develops from inhaling mining dust? (iii) Why do mining regions face severe river pollution? (iv) Suggest one mandatory safety regulation.', NULL, NULL, 'CASE', 'Social Science', 'Minerals and Energy Resources', 4, '(i) Asphyxiation, coal-mine fires, flooding, and roof collapse. (ii) Pulmonary diseases / Silicosis / Pneumoconiosis. (iii) Dumping mineral waste and slurry washes toxic sediments into streams. (iv) Strict safety standards, ventilation, and environmental restoration.', '4 × 1M = 4M', 'Miners working deep underground constantly inhale fine particulate dust and methane fumes, risking fatal roof collapses, flooding, and severe occupational lung ailments.', '(i) Asphyxiation, coal-mine fires, flooding, and roof collapse. (ii) Pulmonary diseases / Silicosis / Pneumoconiosis. (iii) Dumping mineral waste and slurry washes toxic sediments into streams. (iv) Strict safety standards, ventilation, and environmental restoration.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000006d', 'Which industry is known as the basic / key industry because all heavy, medium, and light industries depend on it for machinery?', '{"A":"Textile industry","B":"Iron and Steel industry","C":"Sugar industry","D":"IT industry"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Manufacturing Industries', 1, 'Steel supplies machinery, construction, defence, and tools.', NULL, NULL, 'Steel supplies machinery, construction, defence, and tools.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000006e', 'Which city is called the "Electronic Capital of India"?', '{"A":"Mumbai","B":"Bengaluru","C":"Pune","D":"Hyderabad"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Manufacturing Industries', 1, 'Bengaluru leads India''s IT and electronics hub.', NULL, NULL, 'Bengaluru leads India''s IT and electronics hub.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000006f', 'First successful cotton textile mill in India was established in 1854 in:', '{"A":"Ahmedabad","B":"Mumbai","C":"Kolkata","D":"Surat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Manufacturing Industries', 1, 'Mumbai''s first cotton mill started in 1854.', NULL, NULL, 'Mumbai''s first cotton mill started in 1854.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000070', 'Which public-sector steel plant was built in Chhattisgarh and why is Chota Nagpur Plateau ideal for steel?', '{"A":"Bhilai Steel Plant; close to iron ore, coking coal, limestone & cheap labour","B":"Salem Steel Plant","C":"Rourkela in Kerala","D":"Durgapur in Rajasthan"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Manufacturing Industries', 1, 'Chota Nagpur combines raw materials, rail network, and market.', NULL, NULL, 'Chota Nagpur combines raw materials, rail network, and market.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000071', 'Which industry consumes its own weight-losing seasonal raw material, making location near sugarcane fields essential?', '{"A":"Jute","B":"Sugar industry","C":"Aluminium","D":"Cement"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Manufacturing Industries', 1, 'Sucrose content dries up rapidly in haulage.', NULL, NULL, 'Sucrose content dries up rapidly in haulage.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000072', 'Assertion (A): In recent years, there is a tendency for sugar mills to shift toward southern and western states like Maharashtra.
Reason (R): Cane produced in southern/western states has higher sucrose content and cooler climate ensures a longer crushing season.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Manufacturing Industries', 1, 'Cooperative success + higher sucrose explain the shift.', NULL, NULL, 'Cooperative success + higher sucrose explain the shift.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000073', 'Why is manufacturing considered the backbone of economic development in India?', NULL, NULL, 'VSA', 'Social Science', 'Manufacturing Industries', 2, 'Modernises agriculture, reduces heavy dependence on farm income by creating secondary/tertiary jobs, boosts foreign exchange via manufactured exports, and eradicates poverty.', 'Any 2–3 clear points (2M)', NULL, 'Modernises agriculture, reduces heavy dependence on farm income by creating secondary/tertiary jobs, boosts foreign exchange via manufactured exports, and eradicates poverty.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000074', 'Distinguish between Agro-based and Mineral-based industries with two examples each.', NULL, NULL, 'VSA', 'Social Science', 'Manufacturing Industries', 2, 'Agro-based use agricultural raw materials (cotton textile, jute, sugar, edible oil). Mineral-based use minerals/metals (iron & steel, cement, aluminium, petrochemicals).', '1M each', NULL, 'Agro-based use agricultural raw materials (cotton textile, jute, sugar, edible oil). Mineral-based use minerals/metals (iron & steel, cement, aluminium, petrochemicals).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000075', 'Explain three reasons why the Cotton Textile industry was initially concentrated in the cotton-growing belt of Maharashtra and Gujarat.', NULL, NULL, 'SA', 'Social Science', 'Manufacturing Industries', 3, 'Availability of raw cotton, moist coastal climate (prevents yarn snapping), accessible market, port facilities (Mumbai/Kandla), transport network, and abundant labour.', '3 reasons × 1M', NULL, 'Availability of raw cotton, moist coastal climate (prevents yarn snapping), accessible market, port facilities (Mumbai/Kandla), transport network, and abundant labour.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000076', 'How do agriculture and manufacturing industries move hand in hand? Explain with examples.', NULL, NULL, 'SA', 'Social Science', 'Manufacturing Industries', 3, 'Agro-industries depend on agriculture for raw materials (cotton, sugarcane, jute) while manufacturing boosts farm productivity by supplying irrigation pumps, fertilisers, pesticides, PVC pipes, and tractors.', 'Both directions explained (3M)', NULL, 'Agro-industries depend on agriculture for raw materials (cotton, sugarcane, jute) while manufacturing boosts farm productivity by supplying irrigation pumps, fertilisers, pesticides, PVC pipes, and tractors.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000077', 'Explain four types of pollution caused by industries and describe five concrete steps taken by industries (like NTPC) to control environmental degradation.', NULL, NULL, 'LA', 'Social Science', 'Manufacturing Industries', 5, 'Air (SO₂/CO/particulates), Water (dyes, acids, heavy metals), Thermal (hot water discharged into rivers harming aquatic life), Noise (machinery/generators damaging hearing/BP). Control: reusing/recycling water, rainwater harvesting, electrostatic precipitators/scrubbers, fitting silencers, NTPC ash-pond management & green-belt afforestation.', '4 pollution types (2.5M) + 5 control measures (2.5M)', NULL, 'Air (SO₂/CO/particulates), Water (dyes, acids, heavy metals), Thermal (hot water discharged into rivers harming aquatic life), Noise (machinery/generators damaging hearing/BP). Control: reusing/recycling water, rainwater harvesting, electrostatic precipitators/scrubbers, fitting silencers, NTPC ash-pond management & green-belt afforestation.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000078', '(i) What ratio of iron ore, coking coal, and limestone is needed to make steel? (ii) Why does India still struggle to reach full steel potential despite raw materials? (iii) Mention two uses of aluminium smelting. (iv) What does "integrated steel plant" mean?', NULL, NULL, 'CASE', 'Social Science', 'Manufacturing Industries', 4, '(i) Approximately 4 : 2 : 1 (with manganese added to harden steel). (ii) High cost & limited availability of coking coal, lower labour productivity, irregular power, poor infrastructure. (iii) Aircrafts, utensils, electrical cables. (iv) Large plant handling everything from raw ore smelting to rolling and shaping steel.', '4 × 1M = 4M', 'Iron and steel is a heavy industry because all raw materials and finished products are bulky, incurring heavy transportation costs unless plants sit near mineral belts.', '(i) Approximately 4 : 2 : 1 (with manganese added to harden steel). (ii) High cost & limited availability of coking coal, lower labour productivity, irregular power, poor infrastructure. (iii) Aircrafts, utensils, electrical cables. (iv) Large plant handling everything from raw ore smelting to rolling and shaping steel.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000079', 'Which major port on the east coast is the deepest landlocked and well-protected port in India?', '{"A":"Chennai","B":"Visakhapatnam","C":"Haldia","D":"Tuticorin"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Lifelines of National Economy', 1, 'Visakhapatnam is India''s deepest landlocked port.', NULL, NULL, 'Visakhapatnam is India''s deepest landlocked port.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007a', 'Kandla (Deendayal Port) in Kachchh was the first port developed soon after Independence to ease trade volume on:', '{"A":"Kolkata port","B":"Mumbai port (after Karachi went to Pakistan)","C":"Chennai port","D":"Kochi port"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Lifelines of National Economy', 1, 'Built in Gujarat to compensate for Karachi loss and decongest Mumbai.', NULL, NULL, 'Built in Gujarat to compensate for Karachi loss and decongest Mumbai.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007b', 'Which riverine tidal port in India requires constant dredging of the Hugli river?', '{"A":"Paradip","B":"Kolkata (Haldia)","C":"Marmagao","D":"New Mangalore"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Lifelines of National Economy', 1, 'Kolkata is an inland riverine port.', NULL, NULL, 'Kolkata is an inland riverine port.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007c', 'Which port along the Malabar coast in Kerala is located at the entrance of a lagoon with a natural harbour?', '{"A":"Kochi","B":"Marmagao","C":"Kandla","D":"Ennore"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Lifelines of National Economy', 1, 'Kochi sits at the entrance of Vembanad lagoon.', NULL, NULL, 'Kochi sits at the entrance of Vembanad lagoon.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007d', 'Which port in Goa accounts for about 50% of India''s iron ore export?', '{"A":"Marmagao","B":"New Mangalore","C":"Mumbai","D":"Kandla"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Lifelines of National Economy', 1, 'Marmagao is India''s premier iron-ore exporting port.', NULL, NULL, 'Marmagao is India''s premier iron-ore exporting port.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007e', 'Assertion (A): Waterways are the cheapest means of transport for heavy and bulky goods.
Reason (R): Water transport is fuel-efficient and environment-friendly with minimal friction and track maintenance.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Lifelines of National Economy', 1, 'Lower fuel per tonne-km makes waterways economical.', NULL, NULL, 'Lower fuel per tonne-km makes waterways economical.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000007f', 'Name the two major ports of Tamil Nadu and state one special feature of Chennai port.', NULL, NULL, 'VSA', 'Social Science', 'Lifelines of National Economy', 2, 'Chennai and Tuticorin (V.O. Chidambaranar). Chennai is one of the oldest artificial ports in India, second only to Mumbai in trade volume.', 'Two ports (1M) + Chennai feature (1M)', NULL, 'Chennai and Tuticorin (V.O. Chidambaranar). Chennai is one of the oldest artificial ports in India, second only to Mumbai in trade volume.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000080', 'Why are border roads and the Golden Quadrilateral highway network vital for India?', NULL, NULL, 'VSA', 'Social Science', 'Lifelines of National Economy', 2, 'Golden Quadrilateral (6-lane superhighways linking Delhi-Kolkata-Chennai-Mumbai) cuts travel time between mega cities; Border Roads (BRO) strengthen strategic northern/northeastern frontier access and economic upliftment.', '1M each', NULL, 'Golden Quadrilateral (6-lane superhighways linking Delhi-Kolkata-Chennai-Mumbai) cuts travel time between mega cities; Border Roads (BRO) strengthen strategic northern/northeastern frontier access and economic upliftment.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000081', 'State three advantages of pipeline transport for crude oil, petroleum products, and natural gas (mention HVJ pipeline).', NULL, NULL, 'SA', 'Social Science', 'Lifelines of National Economy', 3, 'Ensures continuous uninterrupted supply across tough terrain; initial laying cost is high but running costs are minimal; eliminates trans-shipment delays/losses. Example: Hazira–Vijaipur–Jagdishpur (HVJ) cross-country gas pipeline.', '2 advantages + HVJ example (3M)', NULL, 'Ensures continuous uninterrupted supply across tough terrain; initial laying cost is high but running costs are minimal; eliminates trans-shipment delays/losses. Example: Hazira–Vijaipur–Jagdishpur (HVJ) cross-country gas pipeline.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000082', 'Why is air travel preferred in North-Eastern India despite higher fares?', NULL, NULL, 'SA', 'Social Science', 'Lifelines of National Economy', 3, 'North-East has big dissected rivers, dense forests, frequent floods, and international borders making road/rail construction difficult, whereas airways glide swiftly across terrain.', '3 terrain/strategic points × 1M', NULL, 'North-East has big dissected rivers, dense forests, frequent floods, and international borders making road/rail construction difficult, whereas airways glide swiftly across terrain.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000083', 'Identify and state the significance of five major sea ports along India''s coastline (3 on West Coast, 2 on East Coast) and explain why a dense transport & communication network is essential for international trade.', NULL, NULL, 'LA', 'Social Science', 'Lifelines of National Economy', 5, 'West: Kandla (tidal, Gujarat), Mumbai (largest natural harbour), Marmagao (iron ore, Goa), New Mangalore (Kudremukh iron ore), Kochi (lagoon natural harbour). East: Tuticorin, Chennai (oldest artificial), Visakhapatnam (deepest landlocked), Paradip (iron ore), Kolkata (riverine). Dense networks act as lifelines linking local producers to global markets.', '5 ports with details (3.5M) + Trade linkage role (1.5M)', NULL, 'West: Kandla (tidal, Gujarat), Mumbai (largest natural harbour), Marmagao (iron ore, Goa), New Mangalore (Kudremukh iron ore), Kochi (lagoon natural harbour). East: Tuticorin, Chennai (oldest artificial), Visakhapatnam (deepest landlocked), Paradip (iron ore), Kolkata (riverine). Dense networks act as lifelines linking local producers to global markets.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000084', '(i) Name National Waterway No. 1 and its stretch. (ii) Which river forms NW-2 in Assam? (iii) How does Mumbai port differ from Jawaharlal Nehru Port? (iv) Why is tourism considered an invisible trade?', NULL, NULL, 'CASE', 'Social Science', 'Lifelines of National Economy', 4, '(i) Ganga river between Prayagraj (Allahabad) and Haldia (1620 km). (ii) Brahmaputra (Sadiya–Dhubri, 891 km). (iii) JNPT was planned as a modern hub port to decongest Mumbai port. (iv) Promotes national integration, supports handicrafts, earns foreign exchange without exporting physical goods.', '4 × 1M = 4M', 'India''s 7,516.6 km coastline houses 12 major and 200 notified non-major ports, handling 95% of India''s foreign trade volume via oceanic routes and inland waterways.', '(i) Ganga river between Prayagraj (Allahabad) and Haldia (1620 km). (ii) Brahmaputra (Sadiya–Dhubri, 891 km). (iii) JNPT was planned as a modern hub port to decongest Mumbai port. (iv) Promotes national integration, supports handicrafts, earns foreign exchange without exporting physical goods.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000085', 'In Belgium, what percentage of the population in the capital city Brussels spoke French?', '{"A":"20%","B":"59%","C":"80%","D":"40%"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Power Sharing', 1, 'Nationally 59% Dutch & 40% French, but in Brussels 80% spoke French and 20% Dutch.', NULL, NULL, 'Nationally 59% Dutch & 40% French, but in Brussels 80% spoke French and 20% Dutch.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000086', 'Sri Lanka passed an Act in 1956 recognising which language as the only official language?', '{"A":"Tamil","B":"Sinhala","C":"English","D":"Pali"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Power Sharing', 1, 'The 1956 Act imposed Sinhala-only majoritarianism.', NULL, NULL, 'The 1956 Act imposed Sinhala-only majoritarianism.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000087', 'Power shared among Legislature, Executive, and Judiciary is known as:', '{"A":"Vertical division of power","B":"Horizontal distribution of power (checks and balances)","C":"Community government","D":"Coalition government"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Power Sharing', 1, 'Organs at the same level exercise different powers with mutual checks.', NULL, NULL, 'Organs at the same level exercise different powers with mutual checks.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000088', 'Prudential reason for power sharing stresses that power sharing:', '{"A":"Is the very spirit of democracy","B":"Reduces the possibility of conflict between social groups and ensures political stability","C":"Gives all power to majority","D":"Abolishes elections"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Power Sharing', 1, 'Prudential = practical reduction of violence and stability; Moral = democratic spirit.', NULL, NULL, 'Prudential = practical reduction of violence and stability; Moral = democratic spirit.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000089', 'Which third tier of government in Belgium handles cultural, educational, and language-related issues?', '{"A":"Federal government","B":"Community government","C":"State government","D":"Municipal council"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Power Sharing', 1, 'Elected by people belonging to Dutch, French, and German language communities.', NULL, NULL, 'Elected by people belonging to Dutch, French, and German language communities.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000008a', 'Assertion (A): Majoritarianism in Sri Lanka alienated Sri Lankan Tamils and led to a long civil war.
Reason (R): Sri Lankan leaders refused power sharing, favoured Sinhalas in university/government jobs, and denied Tamils equal political rights.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Power Sharing', 1, 'Exclusion sparked ethnic conflict.', NULL, NULL, 'Exclusion sparked ethnic conflict.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000008b', 'Contrast the prudential reason and moral reason for power sharing in a democracy.', NULL, NULL, 'VSA', 'Social Science', 'Power Sharing', 2, 'Prudential reason brings out better outcomes (reduces social conflict, prevents violence and majority tyranny). Moral reason highlights that power sharing is the very spirit of democracy where citizens have a right to be consulted.', '1M each', NULL, 'Prudential reason brings out better outcomes (reduces social conflict, prevents violence and majority tyranny). Moral reason highlights that power sharing is the very spirit of democracy where citizens have a right to be consulted.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000008c', 'Explain the ethnic composition of Sri Lanka (Sinhalas, Sri Lankan Tamils, Indian Tamils).', NULL, NULL, 'VSA', 'Social Science', 'Power Sharing', 2, 'Sinhala-speakers ~74% (mostly Buddhist), Tamil-speakers ~18% (13% Sri Lankan Tamils + ~5% Indian Tamils), and ~7% Christians speaking both Tamil and Sinhala.', 'Exact proportions & groups (2M)', NULL, 'Sinhala-speakers ~74% (mostly Buddhist), Tamil-speakers ~18% (13% Sri Lankan Tamils + ~5% Indian Tamils), and ~7% Christians speaking both Tamil and Sinhala.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000008d', 'State three key elements of the Belgian Model of accommodation (1970–1993) that preserved unity.', NULL, NULL, 'SA', 'Social Science', 'Power Sharing', 3, '(1) Equal number of Dutch and French-speaking ministers in central government (no unilateral decision). (2) Many powers transferred to state governments (not subordinate to centre). (3) Separate government in Brussels with equal representation + Community government for cultural/language matters.', '3 elements × 1M', NULL, '(1) Equal number of Dutch and French-speaking ministers in central government (no unilateral decision). (2) Many powers transferred to state governments (not subordinate to centre). (3) Separate government in Brussels with equal representation + Community government for cultural/language matters.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000008e', 'Describe three forms of power sharing practiced in modern democracies with one Indian example each.', NULL, NULL, 'SA', 'Social Science', 'Power Sharing', 3, '(1) Horizontal among Legislature, Executive, Judiciary (Supreme Court judicial review). (2) Vertical/Federal across Union, State, Panchayats. (3) Among political parties & pressure groups (NDA/UPA coalitions).', '3 forms × 1M', NULL, '(1) Horizontal among Legislature, Executive, Judiciary (Supreme Court judicial review). (2) Vertical/Federal across Union, State, Panchayats. (3) Among political parties & pressure groups (NDA/UPA coalitions).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000008f', 'Compare how Belgium and Sri Lanka dealt differently with the question of power sharing. What lessons do both countries teach modern multi-ethnic democracies?', NULL, NULL, 'LA', 'Social Science', 'Power Sharing', 5, 'Belgium amended its constitution four times to accommodate linguistic diversity via equal central cabinet representation, Brussels parity, and Community governments — keeping peace and hosting the EU HQ. Sri Lanka enforced Sinhala-only majoritarianism (1956), preferential jobs, and ignored Tamil autonomy demands — sparking decades of civil war. Lesson: respecting diverse communities strengthens national unity; majority rule destroys it.', 'Belgium comparison (2M) + Sri Lanka comparison (2M) + Democratic lesson (1M)', NULL, 'Belgium amended its constitution four times to accommodate linguistic diversity via equal central cabinet representation, Brussels parity, and Community governments — keeping peace and hosting the EU HQ. Sri Lanka enforced Sinhala-only majoritarianism (1956), preferential jobs, and ignored Tamil autonomy demands — sparking decades of civil war. Lesson: respecting diverse communities strengthens national unity; majority rule destroys it.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000090', '(i) Why did Dutch-speaking Belgians feel resentful in the 1950s–60s? (ii) Why is Brussels often called a "special problem"? (iii) Which city became headquarters of the European Union? (iv) Name two languages spoken in Belgium besides Dutch and French.', NULL, NULL, 'CASE', 'Social Science', 'Power Sharing', 4, '(i) Though a national majority (59%), Dutch speakers received economic and educational benefits much later than the wealthier French-speaking minority. (ii) Majority of country (Dutch) was minority in the capital Brussels (20% vs 80% French). (iii) Brussels. (iv) German (1% in eastern Belgium).', '4 × 1M = 4M', 'Of Belgium''s population, 59% live in the Flemish region speaking Dutch, 40% live in Wallonia speaking French, and 1% speak German, creating a sharp contrast in Brussels.', '(i) Though a national majority (59%), Dutch speakers received economic and educational benefits much later than the wealthier French-speaking minority. (ii) Majority of country (Dutch) was minority in the capital Brussels (20% vs 80% French). (iii) Brussels. (iv) German (1% in eastern Belgium).', 'HARD', true),
        ('10031111-0000-4000-8000-000000000091', 'Which subjects fall under the Concurrent List in the Indian Constitution?', '{"A":"Defence and Foreign Affairs","B":"Police and Agriculture","C":"Education, Forests, Marriage, Adoption","D":"Currency and Banking"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Federalism', 1, 'Education, forests, trade unions, marriage, adoption are Concurrent List subjects.', NULL, NULL, 'Education, forests, trade unions, marriage, adoption are Concurrent List subjects.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000092', 'If a conflict arises between Central and State laws on a Concurrent List subject, whose law prevails?', '{"A":"State Government","B":"Central (Union) Government","C":"High Court","D":"Panchayat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Federalism', 1, 'Union law overrides State law in case of conflict on Concurrent subjects.', NULL, NULL, 'Union law overrides State law in case of conflict on Concurrent subjects.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000093', 'USA, Switzerland, and Australia are examples of which type of federation?', '{"A":"Holding together federation","B":"Coming together federation","C":"Unitary state","D":"Confederation only"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Federalism', 1, 'Independent states pooled sovereignty into a "coming together" federation with equal state powers.', NULL, NULL, 'Independent states pooled sovereignty into a "coming together" federation with equal state powers.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000094', 'How many languages are recognised as Scheduled Languages in the Eighth Schedule of the Indian Constitution?', '{"A":"14","B":"18","C":"22","D":"25"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Federalism', 1, '22 Scheduled Languages (Hindi + 21 others).', NULL, NULL, '22 Scheduled Languages (Hindi + 21 others).', 'EASY', true),
        ('10031111-0000-4000-8000-000000000095', 'Which constitutional amendment of 1992 empowered rural and urban local self-governments (Panchayats & Municipalities)?', '{"A":"42nd Amendment","B":"73rd and 74th Amendments","C":"86th Amendment","D":"44th Amendment"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Federalism', 1, '1992 Amendments created the third tier with regular elections and 1/3rd women reservation.', NULL, NULL, '1992 Amendments created the third tier with regular elections and 1/3rd women reservation.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000096', 'Assertion (A): India is a "holding together" federation rather than a "coming together" federation.
Reason (R): A large country decided to divide power between constituent states and the national government, giving some units special status (Art. 371).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Federalism', 1, 'Central government tends to be stronger in holding together federations.', NULL, NULL, 'Central government tends to be stronger in holding together federations.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000097', 'What is a Coalition Government and how did coalition politics after 1990 strengthen Indian federalism?', NULL, NULL, 'VSA', 'Social Science', 'Federalism', 2, 'A government formed by coming together of at least two political parties. After 1990, regional parties became vital partners at the Centre, discouraging arbitrary dismissal of state governments.', 'Definition (1M) + Impact on federalism (1M)', NULL, 'A government formed by coming together of at least two political parties. After 1990, regional parties became vital partners at the Centre, discouraging arbitrary dismissal of state governments.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000098', 'Who holds "Residuary Subjects" in India? Give two examples.', NULL, NULL, 'VSA', 'Social Science', 'Federalism', 2, 'The Union (Central) Government legislates on residuary subjects not in any list (e.g., computer software, cyber laws, e-commerce).', 'Union Govt (1M) + Examples (1M)', NULL, 'The Union (Central) Government legislates on residuary subjects not in any list (e.g., computer software, cyber laws, e-commerce).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000099', 'Distinguish between "Coming Together" and "Holding Together" federations with two examples each.', NULL, NULL, 'SA', 'Social Science', 'Federalism', 3, 'Coming Together: independent states unite equally (USA, Switzerland, Australia); all constituent states usually hold equal power. Holding Together: a large country shares power internally (India, Spain, Belgium); central government is stronger and units may have unequal powers.', '1.5M each', NULL, 'Coming Together: independent states unite equally (USA, Switzerland, Australia); all constituent states usually hold equal power. Holding Together: a large country shares power internally (India, Spain, Belgium); central government is stronger and units may have unequal powers.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000009a', 'Explain how the Linguistic States reorganisation and Language Policy tested and strengthened Indian federalism.', NULL, NULL, 'SA', 'Social Science', 'Federalism', 3, 'Creating linguistic states (despite initial fears of disintegration) made administration easier and united the nation. Flexible language policy (no single national language, Hindi + English + 22 Scheduled Languages) avoided Sri Lanka-style ethnic conflict.', 'Linguistic States (1.5M) + Language Policy (1.5M)', NULL, 'Creating linguistic states (despite initial fears of disintegration) made administration easier and united the nation. Flexible language policy (no single national language, Hindi + English + 22 Scheduled Languages) avoided Sri Lanka-style ethnic conflict.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000009b', 'Explain five key features of Federalism. Highlight the major steps taken in 1992 toward Decentralisation in India (local self-government).', NULL, NULL, 'LA', 'Social Science', 'Federalism', 5, 'Features: 2+ tiers; same citizens different jurisdictions; constitutionally specified powers; independent courts interpret disputes; dual objective (unity & diversity). 1992 Decentralisation: constitutionally mandatory regular elections; SC/ST/OBC reservation; 1/3rd seats reserved for women; independent State Election Commission; mandatory revenue sharing.', 'Features (2.5M) + 1992 Decentralisation steps (2.5M)', NULL, 'Features: 2+ tiers; same citizens different jurisdictions; constitutionally specified powers; independent courts interpret disputes; dual objective (unity & diversity). 1992 Decentralisation: constitutionally mandatory regular elections; SC/ST/OBC reservation; 1/3rd seats reserved for women; independent State Election Commission; mandatory revenue sharing.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000009c', '(i) What is the head of a Gram Panchayat called? (ii) Who supervises the work of Gram Panchayat in a village? (iii) What are Block-level and District-level rural bodies called? (iv) Name the political head of a Municipal Corporation.', NULL, NULL, 'CASE', 'Social Science', 'Federalism', 4, '(i) Sarpanch / President. (ii) Gram Sabha (all adult voters of village meeting twice/thrice a year). (iii) Panchayat Samiti (Block) and Zilla Parishad (District). (iv) Mayor.', '4 × 1M = 4M', 'Decentralisation brings decision-making closer to villages and towns because local people possess deeper knowledge of local water, sanitation, and school priorities.', '(i) Sarpanch / President. (ii) Gram Sabha (all adult voters of village meeting twice/thrice a year). (iii) Panchayat Samiti (Block) and Zilla Parishad (District). (iv) Mayor.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000009d', 'A person who believes in equal rights and opportunities for women and men is called a:', '{"A":"Communalist","B":"Feminist","C":"Secularist","D":"Patriarch"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Gender, Religion and Caste', 1, 'Feminist movements seek political, legal, and social gender equality.', NULL, NULL, 'Feminist movements seek political, legal, and social gender equality.', 'EASY', true),
        ('10031111-0000-4000-8000-00000000009e', 'What proportion of seats are reserved for women in Indian local self-government bodies (Panchayats & Municipalities)?', '{"A":"One-fourth","B":"One-third","C":"One-half","D":"One-fifth"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Gender, Religion and Caste', 1, 'One-third (and Nari Shakti Vandan Adhiniyam 2023 passed for 33% in Lok Sabha/Assemblies).', NULL, NULL, 'One-third (and Nari Shakti Vandan Adhiniyam 2023 passed for 33% in Lok Sabha/Assemblies).', 'EASY', true),
        ('10031111-0000-4000-8000-00000000009f', 'Equal Remuneration Act guaranteeing equal wages for equal work regardless of gender was passed in:', '{"A":"1956","B":"1976","C":"1986","D":"1992"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Gender, Religion and Caste', 1, 'Equal Remuneration Act, 1976.', NULL, NULL, 'Equal Remuneration Act, 1976.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000a0', 'Which constitutional provision proves India is a Secular State?', '{"A":"One official religion","B":"No official religion; freedom to profess, practise, propagate any religion (Art. 25–28)","C":"Religion decides voting rights","D":"Religious tax levied"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Gender, Religion and Caste', 1, 'India treats all religions neutrally without official state religion.', NULL, NULL, 'India treats all religions neutrally without official state religion.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000a1', 'Use of religion in politics by projecting one religion as superior to others and using state power to dominate is called:', '{"A":"Secularism","B":"Communalism","C":"Federalism","D":"Socialism"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Gender, Religion and Caste', 1, 'Communal politics equates religious community with nation.', NULL, NULL, 'Communal politics equates religious community with nation.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000a2', 'Assertion (A): The percentage of elected women members in India''s Lok Sabha has historically remained very low compared to global averages.
Reason (R): Despite equal voting rights, patriarchal candidate selection and lack of legislative quotas earlier kept women''s representation below 15%.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Gender, Religion and Caste', 1, 'Structural barriers limited Lok Sabha representation.', NULL, NULL, 'Structural barriers limited Lok Sabha representation.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000a3', 'What is "Sexual Division of Labour"? State one consequence of it in public life.', NULL, NULL, 'VSA', 'Social Science', 'Gender, Religion and Caste', 2, 'A system in which all work inside the home is done by women or organised through domestic helpers, while men perform paid outside work — leading to undervaluation of women''s labour and low public/political presence.', '1M each', NULL, 'A system in which all work inside the home is done by women or organised through domestic helpers, while men perform paid outside work — leading to undervaluation of women''s labour and low public/political presence.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000a4', 'Why did Gandhiji say religion can never be separated from politics?', NULL, NULL, 'VSA', 'Social Science', 'Gender, Religion and Caste', 2, 'He meant moral values and ethical principles drawn from all religions should guide politics cleanly, NOT religious sectarianism or communal hatred.', 'Moral ethics meaning (2M)', NULL, 'He meant moral values and ethical principles drawn from all religions should guide politics cleanly, NOT religious sectarianism or communal hatred.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000a5', 'Describe three forms that Communalism can take in everyday politics.', NULL, NULL, 'SA', 'Social Science', 'Gender, Religion and Caste', 3, '(1) Everyday prejudices and stereotypes of religious superiority. (2) Quest for political dominance (majoritarianism or minority separatism). (3) Political mobilisation using sacred symbols, emotional appeals, and in worst form communal riots/violence.', '3 forms × 1M', NULL, '(1) Everyday prejudices and stereotypes of religious superiority. (2) Quest for political dominance (majoritarianism or minority separatism). (3) Political mobilisation using sacred symbols, emotional appeals, and in worst form communal riots/violence.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000a6', 'State three reasons why caste inequalities have declined significantly in modern India yet have not completely disappeared.', NULL, NULL, 'SA', 'Social Science', 'Gender, Religion and Caste', 3, 'Declined due to social reformers (Phule, Gandhi, Ambedkar), urbanisation, occupational mobility, literacy, and constitutional ban on untouchability. Still persists: most marry within own caste, economic status still correlates with historic caste privilege/disadvantage.', 'Decline factors (1.5M) + Persistence factors (1.5M)', NULL, 'Declined due to social reformers (Phule, Gandhi, Ambedkar), urbanisation, occupational mobility, literacy, and constitutional ban on untouchability. Still persists: most marry within own caste, economic status still correlates with historic caste privilege/disadvantage.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000a7', 'Examine how Caste gets politicised and how Politics influences the Caste system (both positive and negative aspects).', NULL, NULL, 'LA', 'Social Science', 'Gender, Religion and Caste', 5, 'Politics in caste: parties pick candidates matching constituency caste mix, form multi-caste coalitions, appeal to caste sentiments (negative vote-bank risk). Conversely, caste in politics: caste groups widen by uniting sub-castes (forward/backward), enter bargaining coalitions giving disadvantaged Dalit/OBC communities voice and dignity in power.', 'Caste in politics (2.5M) + Politics influencing caste (2.5M)', NULL, 'Politics in caste: parties pick candidates matching constituency caste mix, form multi-caste coalitions, appeal to caste sentiments (negative vote-bank risk). Conversely, caste in politics: caste groups widen by uniting sub-castes (forward/backward), enter bargaining coalitions giving disadvantaged Dalit/OBC communities voice and dignity in power.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000a8', '(i) Mention two indicators showing women still face disadvantage in India despite progress. (ii) What caused declining child sex ratio in some regions? (iii) How does the Women''s Reservation Act, 2023 address political representation? (iv) Name one constitutional right ensuring religious equality.', NULL, NULL, 'CASE', 'Social Science', 'Gender, Religion and Caste', 4, '(i) Lower female literacy rate, unpaid domestic burden, lower average wages than men despite Equal Remuneration Act. (ii) Preference for sons leading to illegal sex-selective abortion. (iii) Reserves 33% seats for women in Lok Sabha, State Assemblies, and Delhi Assembly. (iv) Right to Equality (Art. 14-15) / Freedom of Religion (Art. 25).', '4 × 1M = 4M', 'Census figures highlight steady improvements in female schooling and workforce participation, yet severe social gaps remain across literacy, child sex ratio, equal pay, and parliamentary seats.', '(i) Lower female literacy rate, unpaid domestic burden, lower average wages than men despite Equal Remuneration Act. (ii) Preference for sons leading to illegal sex-selective abortion. (iii) Reserves 33% seats for women in Lok Sabha, State Assemblies, and Delhi Assembly. (iv) Right to Equality (Art. 14-15) / Freedom of Religion (Art. 25).', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000a9', 'How many components does a political party consist of?', '{"A":"Two","B":"Three (Leaders, Active Members, Followers)","C":"Four","D":"Five"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Parties', 1, 'Leaders, Active Members, and Followers.', NULL, NULL, 'Leaders, Active Members, and Followers.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000aa', 'A party that secures at least 6% of total votes in Lok Sabha/Assembly elections in 4 states AND wins at least 4 Lok Sabha seats is recognised as a:', '{"A":"State Party","B":"National Party","C":"Coalition Front","D":"Pressure Group"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Parties', 1, 'Election Commission criterion for National Party status.', NULL, NULL, 'Election Commission criterion for National Party status.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ab', 'Anti-Defection Law prevents elected MLAs/MPs from changing parties after elections to curb:', '{"A":"Voters turnout","B":"Horse-trading and switching for ministerial/cash rewards","C":"Public debates","D":"Independent candidates"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Parties', 1, 'Added by 52nd Amendment (10th Schedule): defectors lose seat.', NULL, NULL, 'Added by 52nd Amendment (10th Schedule): defectors lose seat.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ac', 'India follows which type of party system?', '{"A":"One-party system","B":"Two-party system","C":"Multi-party system","D":"Partyless democracy"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Political Parties', 1, 'Diverse social and geographical diversity gives India a multi-party system.', NULL, NULL, 'Diverse social and geographical diversity gives India a multi-party system.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ad', 'Which institution allots official election symbols to recognised national and state political parties?', '{"A":"Supreme Court","B":"Election Commission of India","C":"Parliament","D":"President"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Parties', 1, 'Election Commission registers and recognises parties.', NULL, NULL, 'Election Commission registers and recognises parties.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ae', 'Assertion (A): Opposition parties play a vital role in a healthy democracy.
Reason (R): Parties that lose elections voice different views, criticise government failures, and mobilise public accountability.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Political Parties', 1, 'Opposition checks ruling party excesses.', NULL, NULL, 'Opposition checks ruling party excesses.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000af', 'Define "Partisan" and explain "Defection" in politics.', NULL, NULL, 'VSA', 'Social Science', 'Political Parties', 2, 'Partisan: a person strongly committed to a party, group, or faction (unable to take balanced neutral view). Defection: changing party allegiance from the party on which a person got elected to a different party.', '1M each', NULL, 'Partisan: a person strongly committed to a party, group, or faction (unable to take balanced neutral view). Defection: changing party allegiance from the party on which a person got elected to a different party.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000b0', 'Why are political parties an unavoidable necessity in modern representative democracies?', NULL, NULL, 'VSA', 'Social Science', 'Political Parties', 2, 'Without parties every candidate is independent and unable to promise major policy changes; no one bears responsibility for how the country is run nationally.', 'Policy coherence + Collective accountability (2M)', NULL, 'Without parties every candidate is independent and unable to promise major policy changes; no one bears responsibility for how the country is run nationally.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000b1', 'Explain any three challenges currently faced by political parties in India.', NULL, NULL, 'SA', 'Social Science', 'Political Parties', 3, '(1) Lack of internal democracy (concentration of power in top leaders, rare organisational polls). (2) Dynastic succession (family control over top posts). (3) Growing role of money & muscle power and lack of meaningful ideological choice.', '3 challenges × 1M', NULL, '(1) Lack of internal democracy (concentration of power in top leaders, rare organisational polls). (2) Dynastic succession (family control over top posts). (3) Growing role of money & muscle power and lack of meaningful ideological choice.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000b2', 'Describe three recent institutional steps or Supreme Court orders taken to reform political parties.', NULL, NULL, 'SA', 'Social Science', 'Political Parties', 3, '(1) Anti-Defection Constitutional Amendment barring MLAs/MPs from switching parties. (2) Supreme Court mandatory affidavit disclosing assets and pending criminal cases. (3) Election Commission order making organisational elections and income-tax returns mandatory.', '3 reforms × 1M', NULL, '(1) Anti-Defection Constitutional Amendment barring MLAs/MPs from switching parties. (2) Supreme Court mandatory affidavit disclosing assets and pending criminal cases. (3) Election Commission order making organisational elections and income-tax returns mandatory.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000b3', 'List five major functions performed by political parties in a democracy and suggest three additional ways citizens and law can reform parties further.', NULL, NULL, 'LA', 'Social Science', 'Political Parties', 5, 'Functions: contest elections; put forward policies/programmes; play decisive law-making role; form & run governments; shape public opinion & provide access to govt machinery/welfare schemes (and act as Opposition). Suggestions: law regulating internal party affairs, minimum 1/3rd tickets for women, state funding of elections, public pressure via media/petitions.', '5 functions (3.5M) + 3 future suggestions (1.5M)', NULL, 'Functions: contest elections; put forward policies/programmes; play decisive law-making role; form & run governments; shape public opinion & provide access to govt machinery/welfare schemes (and act as Opposition). Suggestions: law regulating internal party affairs, minimum 1/3rd tickets for women, state funding of elections, public pressure via media/petitions.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000b4', '(i) Differentiate between National Party and State Party recognition criteria. (ii) Name any three National Parties of India. (iii) Why do regional/state parties strengthen federalism? (iv) How can ordinary citizens pressure parties to reform?', NULL, NULL, 'CASE', 'Social Science', 'Political Parties', 4, '(i) State party: >=6% Assembly votes + >=2 seats (or 3% seats); National: >=6% LS/Assembly votes in 4 states + >=4 LS seats. (ii) INC, BJP, BSP, CPI(M), AAP, NPP (any three). (iii) Compel national parties into alliances respecting state aspirations. (iv) Petitions, publicity, agitations, or joining parties directly to change from within.', '4 × 1M = 4M', 'Under India''s multi-party system, dozens of state-level parties partner with national parties to form coalition governments and give regional issues national voice.', '(i) State party: >=6% Assembly votes + >=2 seats (or 3% seats); National: >=6% LS/Assembly votes in 4 states + >=4 LS seats. (ii) INC, BJP, BSP, CPI(M), AAP, NPP (any three). (iii) Compel national parties into alliances respecting state aspirations. (iv) Petitions, publicity, agitations, or joining parties directly to change from within.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000b5', 'Which basic outcome must a democracy be expected to produce first?', '{"A":"Instant 10% GDP growth","B":"An accountable, responsive, and legitimate government","C":"Zero income inequality","D":"One-party dominance"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Outcomes of Democracy', 1, 'Accountability, responsiveness, and legitimacy form the core democratic promise.', NULL, NULL, 'Accountability, responsiveness, and legitimacy form the core democratic promise.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000b6', 'Right to Information (RTI) Act empowers citizens primarily to promote:', '{"A":"Dictatorship","B":"Transparency in government decision-making","C":"Military rule","D":"Tax evasion"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Outcomes of Democracy', 1, 'Transparency lets citizens examine procedures and hold officials accountable.', NULL, NULL, 'Transparency lets citizens examine procedures and hold officials accountable.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000b7', 'A non-democratic regime may take quicker decisions, yet democratic decisions are more:', '{"A":"Secretive","B":"Acceptable to the people and effective long-term because of deliberation","C":"Corrupt always","D":"Irreversible"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Outcomes of Democracy', 1, 'Following norms and public debate increases long-term legitimacy.', NULL, NULL, 'Following norms and public debate increases long-term legitimacy.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000b8', 'In practice, most democracies have fallen short in successfully:', '{"A":"Holding regular elections","B":"Eliminating steep economic inequalities between the ultra-rich and the poor","C":"Allowing political parties","D":"Protecting basic right to vote"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Outcomes of Democracy', 1, 'Political equality (1 person 1 vote) has not guaranteed economic equality.', NULL, NULL, 'Political equality (1 person 1 vote) has not guaranteed economic equality.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000b9', 'Democracy stands much superior to any other form of government in promoting:', '{"A":"Dignity and freedom of the individual","B":"Fastest industrial growth always","C":"Absence of dissent","D":"Censorship"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Outcomes of Democracy', 1, 'Passion for respect and freedom forms the moral bedrock of democracy.', NULL, NULL, 'Passion for respect and freedom forms the moral bedrock of democracy.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ba', 'Assertion (A): Democracy is a legitimate government because it is the people''s own government.
Reason (R): Despite slow bureaucracy or occasional corruption, overwhelming global surveys show citizens prefer elected representatives over dictatorship.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Outcomes of Democracy', 1, 'Citizen consent establishes deep legitimacy.', NULL, NULL, 'Citizen consent establishes deep legitimacy.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000bb', 'Why is there an overwhelming support for democracy across the world even when its economic growth rate sometimes lags behind dictatorships?', NULL, NULL, 'VSA', 'Social Science', 'Outcomes of Democracy', 2, 'Because democracy is a legitimate people''s government that guarantees dignity, freedom, equality, and peaceful conflict correction rather than unchecked tyranny.', 'Legitimacy & dignity reason (2M)', NULL, 'Because democracy is a legitimate people''s government that guarantees dignity, freedom, equality, and peaceful conflict correction rather than unchecked tyranny.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000bc', 'What is "Transparency" in democracy and how do citizens verify government decisions?', NULL, NULL, 'VSA', 'Social Science', 'Outcomes of Democracy', 2, 'Transparency means a citizen has the right and means (such as RTI Act, parliamentary debates, media) to examine the process by which a decision was taken.', 'Definition + RTI/process check (2M)', NULL, 'Transparency means a citizen has the right and means (such as RTI Act, parliamentary debates, media) to examine the process by which a decision was taken.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000bd', 'Mention three conditions a democracy must satisfy to successfully accommodate social diversity.', NULL, NULL, 'SA', 'Social Science', 'Outcomes of Democracy', 3, '(1) Democracy is NOT simply rule by majority opinion; majority must work with minority to represent the general view. (2) Rule by majority must NOT become rule by majority community in religion, race, or language. (3) Every citizen must have a chance of being in the majority at some point.', '2–3 NCERT conditions clearly stated (3M)', NULL, '(1) Democracy is NOT simply rule by majority opinion; majority must work with minority to represent the general view. (2) Rule by majority must NOT become rule by majority community in religion, race, or language. (3) Every citizen must have a chance of being in the majority at some point.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000be', 'Evaluate the performance of democracies on economic growth and reduction of poverty/inequality.', NULL, NULL, 'SA', 'Social Science', 'Outcomes of Democracy', 3, 'Between 1950–2000, dictatorships showed slightly higher average growth rates, though the gap in poor countries is negligible. Democracies cannot guarantee fast economic growth, yet they avoid worst famines. However, democracies have struggled to narrow wealth gaps; small ultra-rich elites still hold disproportionate wealth while bottom classes struggle.', 'Economic growth comparison (1.5M) + Inequality critique (1.5M)', NULL, 'Between 1950–2000, dictatorships showed slightly higher average growth rates, though the gap in poor countries is negligible. Democracies cannot guarantee fast economic growth, yet they avoid worst famines. However, democracies have struggled to narrow wealth gaps; small ultra-rich elites still hold disproportionate wealth while bottom classes struggle.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000bf', 'Examine why complaints and expectations from democracy actually serve as a testimony to its success. Explain how democracy enhances the dignity and freedom of women and disadvantaged castes.', NULL, NULL, 'LA', 'Social Science', 'Outcomes of Democracy', 5, 'Once people taste minimal democratic benefits, they demand higher accountability, better public services, and criticise flaws openly — turning passive subjects into active aware citizens. Dignity: long feminist struggles forced legal and moral equality recognition even if patriarchy lingers; similarly, India''s democratic constitutional guarantees gave disadvantaged castes legal claims to equal status and self-respect.', 'Complaints as success testimony (2.5M) + Women & caste dignity (2.5M)', NULL, 'Once people taste minimal democratic benefits, they demand higher accountability, better public services, and criticise flaws openly — turning passive subjects into active aware citizens. Dignity: long feminist struggles forced legal and moral equality recognition even if patriarchy lingers; similarly, India''s democratic constitutional guarantees gave disadvantaged castes legal claims to equal status and self-respect.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000c0', '(i) Differentiate between Accountable and Responsive government. (ii) Why do democratic procedures take slightly more time? (iii) How does democracy correct its own mistakes? (iv) Give one way citizens exercise control beyond voting once in 5 years.', NULL, NULL, 'CASE', 'Social Science', 'Outcomes of Democracy', 4, '(i) Accountable: answerable to voters & parliament/courts; Responsive: attentive to citizens'' needs & expectations. (ii) Consultation, debate, and due process with multiple stakeholders. (iii) Public space for open discussion lets rulers change policy or voters replace them in next election. (iv) RTI applications, peaceful protests, independent media, PILs.', '4 × 1M = 4M', 'A democratic government may appear slower in clearing infrastructure projects because committees consult affected residents, hold legislative debates, and publish public records before final approval.', '(i) Accountable: answerable to voters & parliament/courts; Responsive: attentive to citizens'' needs & expectations. (ii) Consultation, debate, and due process with multiple stakeholders. (iii) Public space for open discussion lets rulers change policy or voters replace them in next election. (iv) RTI applications, peaceful protests, independent media, PILs.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000c1', 'What is the primary criterion used by the World Bank in classifying different countries?', '{"A":"Literacy Rate","B":"Per Capita Income (Average Income)","C":"Infant Mortality Rate","D":"Life Expectancy"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Development', 1, 'World Bank uses Per Capita Income (GNI per capita).', NULL, NULL, 'World Bank uses Per Capita Income (GNI per capita).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c2', 'Which organisation publishes the Human Development Report comparing Health, Education, and Per Capita Income?', '{"A":"World Bank","B":"UNDP (United Nations Development Programme)","C":"IMF","D":"WTO"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Development', 1, 'UNDP calculates HDI using Life Expectancy, Schooling, and GNI per capita.', NULL, NULL, 'UNDP calculates HDI using Life Expectancy, Schooling, and GNI per capita.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c3', 'Kerala has a much lower Infant Mortality Rate (IMR) than Haryana primarily because Kerala has:', '{"A":"Higher per capita income","B":"Adequate provision of basic health and educational facilities","C":"More coal mines","D":"Larger coastline only"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Development', 1, 'Public health & PDS/schooling lowered IMR despite lower per capita income.', NULL, NULL, 'Public health & PDS/schooling lowered IMR despite lower per capita income.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c4', 'Body Mass Index (BMI) less than 18.5 kg/m² in adults normally indicates:', '{"A":"Overweight","B":"Undernourishment","C":"Obesity","D":"Normal weight"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Development', 1, 'BMI = Weight(kg) / Height(m)²; <18.5 = undernourished, >25 = overweight.', NULL, NULL, 'BMI = Weight(kg) / Height(m)²; <18.5 = undernourished, >25 = overweight.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c5', 'Number of children out of 1000 live births who die before completing one year of age is:', '{"A":"Net Attendance Ratio","B":"Infant Mortality Rate (IMR)","C":"Literacy Rate","D":"Crude Death Rate"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Development', 1, 'Standard definition of IMR.', NULL, NULL, 'Standard definition of IMR.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c6', 'Assertion (A): Different persons can have different as well as conflicting notions of development.
Reason (R): Building a large dam may bring cheap electricity for industrialists while submerging the ancestral lands of tribal communities.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Development', 1, 'Competing needs create conflicting development goals.', NULL, NULL, 'Competing needs create conflicting development goals.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000c7', 'State two limitations of using Per Capita Income as the sole indicator of development.', NULL, NULL, 'VSA', 'Social Science', 'Development', 2, '(1) Average income hides extreme inequality (disparities between rich and poor). (2) Ignores non-material quality-of-life factors like health, clean air, education, freedom, and security.', '1M each', NULL, '(1) Average income hides extreme inequality (disparities between rich and poor). (2) Ignores non-material quality-of-life factors like health, clean air, education, freedom, and security.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000c8', 'Why are public facilities like government hospitals, schools, and PDS essential even for families with decent income?', NULL, NULL, 'VSA', 'Social Science', 'Development', 2, 'Money in your pocket cannot buy a pollution-free environment, unadulterated medicines, or collective security against infectious diseases unless the whole community provides them.', 'Collective goods limitation of private money (2M)', NULL, 'Money in your pocket cannot buy a pollution-free environment, unadulterated medicines, or collective security against infectious diseases unless the whole community provides them.', 'MEDIUM', true)
        ON CONFLICT (id) DO NOTHING;

Reason (R): The value of intermediate goods like wheat and flour is already included inside the price of the final biscuit or bread.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Sectors of the Indian Economy', 1, 'Avoids double counting intermediate inputs.', NULL, NULL, 'Avoids double counting intermediate inputs.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000d3', 'Why are intermediate goods excluded from GDP calculation? Explain with the wheat–flour–biscuit example.', NULL, NULL, 'VSA', 'Social Science', 'Sectors of the Indian Economy', 2, 'Because value of wheat and flour is already included in the price of final biscuits sold to consumers; counting them separately would double or triple count the same output.', 'Double-counting reason (1M) + Example (1M)', NULL, 'Because value of wheat and flour is already included in the price of final biscuits sold to consumers; counting them separately would double or triple count the same output.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000d4', 'Mention two ways to create more employment in rural and semi-rural areas besides crop farming.', NULL, NULL, 'VSA', 'Social Science', 'Sectors of the Indian Economy', 2, 'Setting up dal mills, cold storages, honey collection centres near forests, small-scale food processing, improved rural banking/roads, and promoting tourism/craft.', 'Any 2–3 concrete methods (2M)', NULL, 'Setting up dal mills, cold storages, honey collection centres near forests, small-scale food processing, improved rural banking/roads, and promoting tourism/craft.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000d5', 'Give three reasons for the rising importance of the Tertiary (Service) Sector in India''s GDP.', NULL, NULL, 'SA', 'Social Science', 'Sectors of the Indian Economy', 3, '(1) Rising demand for basic services (hospitals, schools, courts, banks, post, defence). (2) Development of agriculture and industry naturally drives transport, trade, storage. (3) Higher incomes boost tourism, dining, private schools/hospitals + boom in IT & communication services.', '3 reasons × 1M', NULL, '(1) Rising demand for basic services (hospitals, schools, courts, banks, post, defence). (2) Development of agriculture and industry naturally drives transport, trade, storage. (3) Higher incomes boost tourism, dining, private schools/hospitals + boom in IT & communication services.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000d6', 'Compare Organised and Unorganised sectors of employment on three criteria.', NULL, NULL, 'SA', 'Social Science', 'Sectors of the Indian Economy', 3, 'Organised: registered with govt, follows labour laws, fixed hours, paid leave, job security & PF. Unorganised: small/scattered outside govt control, low irregular wages, no overtime/paid leave, job insecurity.', '3 clear comparison points × 1M', NULL, 'Organised: registered with govt, follows labour laws, fixed hours, paid leave, job security & PF. Unorganised: small/scattered outside govt control, low irregular wages, no overtime/paid leave, job insecurity.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000d7', 'Distinguish between Public Sector and Private Sector enterprises with examples. Why must the government spend on Public Sector services (railways, dams, electricity, education) even when Private firms exist?', NULL, NULL, 'LA', 'Social Science', 'Sectors of the Indian Economy', 5, 'Private sector (TISCO, Reliance) aims at profit maximisation. Public sector (Railways, Post Office, NTPC) aims at public welfare. Govt steps in because: huge capital outlays (bridges, railways, harbours) are beyond private reach or take decades to recover; govt supplies affordable electricity/MSP food/schools/healthcare as citizen rights.', 'Distinction (2M) + 3 reasons for public sector necessity (3M)', NULL, 'Private sector (TISCO, Reliance) aims at profit maximisation. Public sector (Railways, Post Office, NTPC) aims at public welfare. Govt steps in because: huge capital outlays (bridges, railways, harbours) are beyond private reach or take decades to recover; govt supplies affordable electricity/MSP food/schools/healthcare as citizen rights.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000d8', '(i) Under which scheme is Laxmi entitled to 100 days of work if she remains unemployed? (ii) What happens if the government fails to provide work within 15 days under MGNREGA? (iii) Identify Laxmi''s problem when 5 family members work on a 2-hectare plot needing only 3. (iv) Name one way irrigation canal construction helps such farmers.', NULL, NULL, 'CASE', 'Social Science', 'Sectors of the Indian Economy', 4, '(i) MGNREGA 2005. (ii) She gets daily unemployment allowance. (iii) Disguised unemployment / underemployment. (iv) Allows sowing a second Rabi crop on the same land, generating year-round employment.', '4 × 1M = 4M', 'Laxmi owns a small unirrigated two-hectare farm plot depending solely on rain to grow jowar and arhar; five adult members of her family work on it throughout the year, though two could easily shift elsewhere without lowering the harvest.', '(i) MGNREGA 2005. (ii) She gets daily unemployment allowance. (iii) Disguised unemployment / underemployment. (iv) Allows sowing a second Rabi crop on the same land, generating year-round employment.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000d9', 'Money eliminates the need for:', '{"A":"Banks","B":"Double coincidence of wants","C":"Interest rates","D":"Loans"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Money and Credit', 1, 'Money acts as an intermediate medium of exchange.', NULL, NULL, 'Money acts as an intermediate medium of exchange.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000da', 'In India, who issues currency notes (except ₹1 notes/coins) on behalf of the Central Government?', '{"A":"SBI","B":"Reserve Bank of India (RBI)","C":"SEBI","D":"NABARD"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Money and Credit', 1, 'RBI holds sole statutory monopoly on currency note issue.', NULL, NULL, 'RBI holds sole statutory monopoly on currency note issue.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000db', 'An asset owned by a borrower (land, building, vehicle, bank deposit) pledged to lender as guarantee until loan repayment is called:', '{"A":"Credit","B":"Collateral","C":"Demand deposit","D":"Cheque"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Money and Credit', 1, 'Collateral protects the lender against default.', NULL, NULL, 'Collateral protects the lender against default.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000dc', 'Why are deposits in bank accounts called "Demand Deposits"?', '{"A":"Banks demand them forcibly","B":"Depositors can withdraw their money on demand at any time","C":"They carry zero value","D":"They are valid only for 1 year"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Money and Credit', 1, 'Withdrawals on demand + cheque payments make them money.', NULL, NULL, 'Withdrawals on demand + cheque payments make them money.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000dd', 'Self-Help Groups (SHGs) typically consist of how many neighbourhood rural women members saving regularly?', '{"A":"5–8 members","B":"15–20 members","C":"50–100 members","D":"200+ members"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Money and Credit', 1, '15–20 members pool savings and get bank loans without collateral.', NULL, NULL, '15–20 members pool savings and get bank loans without collateral.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000de', 'Assertion (A): Poor households still borrow heavily from informal sources like moneylenders despite sky-high interest rates.
Reason (R): Banks require proper documentation and collateral security, which landless poor borrowers frequently lack.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Money and Credit', 1, 'Absence of collateral blocks formal bank credit.', NULL, NULL, 'Absence of collateral blocks formal bank credit.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000df', 'What is a "Cheque"? How do demand deposits and cheques settle payments without cash?', NULL, NULL, 'VSA', 'Social Science', 'Money and Credit', 2, 'A cheque is a paper instructing the bank to pay a specific amount from the drawer''s account to the named person. Money transfers directly between bank accounts without physical cash.', '1M each', NULL, 'A cheque is a paper instructing the bank to pay a specific amount from the drawer''s account to the named person. Money transfers directly between bank accounts without physical cash.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000e0', 'Mention two major risks of borrowing from informal moneylenders (Debt-trap risk).', NULL, NULL, 'VSA', 'Social Science', 'Money and Credit', 2, 'Very high unmonitored interest rates consume large portions of borrower''s income, and harsh recovery methods push small farmers into a vicious debt trap (forced to sell land).', '2 points × 1M', NULL, 'Very high unmonitored interest rates consume large portions of borrower''s income, and harsh recovery methods push small farmers into a vicious debt trap (forced to sell land).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000e1', 'Describe three supervisory functions performed by the Reserve Bank of India (RBI) over formal commercial banks.', NULL, NULL, 'SA', 'Social Science', 'Money and Credit', 3, '(1) Monitors banks to ensure minimum cash reserve balance (CRR) out of deposits. (2) Ensures banks lend not only to profit-making big businesses but also to small cultivators, small-scale industries, and small borrowers. (3) Collects periodic lending data on how much, to whom, and at what interest rates banks lend.', '3 functions × 1M', NULL, '(1) Monitors banks to ensure minimum cash reserve balance (CRR) out of deposits. (2) Ensures banks lend not only to profit-making big businesses but also to small cultivators, small-scale industries, and small borrowers. (3) Collects periodic lending data on how much, to whom, and at what interest rates banks lend.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000e2', 'What are "Terms of Credit"? List its four main components.', NULL, NULL, 'SA', 'Social Science', 'Money and Credit', 3, 'Conditions on which a loan is sanctioned. Four components: Interest rate, Collateral requirement, Documentation requirement, and Mode/duration of repayment.', 'Definition (1M) + 4 components (2M)', NULL, 'Conditions on which a loan is sanctioned. Four components: Interest rate, Collateral requirement, Documentation requirement, and Mode/duration of repayment.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000e3', 'Explain how Self-Help Groups (SHGs) overcome the problem of lack of collateral for poor rural women. Why is cheap and affordable formal credit crucial for a country''s development?', NULL, NULL, 'LA', 'Social Science', 'Money and Credit', 5, 'SHGs (15–20 women) pool small ₹25–₹100 regular savings, lend internally at reasonable interest, and after 1–2 years of regular saving become eligible for collateral-free bank loans sanctioned in the group''s name (building self-reliance & discussing domestic/health issues too). Cheap formal credit lets farmers/entrepreneurs invest in inputs, crops, and factories without falling into debt traps.', 'SHG working & impact (3M) + Cheap credit importance (2M)', NULL, 'SHGs (15–20 women) pool small ₹25–₹100 regular savings, lend internally at reasonable interest, and after 1–2 years of regular saving become eligible for collateral-free bank loans sanctioned in the group''s name (building self-reliance & discussing domestic/health issues too). Cheap formal credit lets farmers/entrepreneurs invest in inputs, crops, and factories without falling into debt traps.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000e4', '(i) Differentiate Swapna''s vs Salim''s credit outcome. (ii) What is a "debt trap"? (iii) Suggest two ways to reduce farmer dependence on village moneylenders. (iv) Name one formal cooperative credit institution in rural areas.', NULL, NULL, 'CASE', 'Social Science', 'Money and Credit', 4, '(i) Salim expanded shoe production and earned profit (positive credit); Swapna suffered crop failure and had to sell land to repay loan (debt trap). (ii) Situation where credit pushes borrower into worse distress from which recovery is painful. (iii) Expand rural cooperative/bank branches & simplified Kisan Credit Cards. (iv) Primary Agricultural Credit Society (PACS) / Cooperative banks.', '4 × 1M = 4M', 'During the festival season, shoe manufacturer Salim takes a loan from his leather supplier and a trader advance to successfully fulfil a 3,000-pair order on time, whereas small groundnut farmer Swapna borrows from a moneylender and loses her crop to pests.', '(i) Salim expanded shoe production and earned profit (positive credit); Swapna suffered crop failure and had to sell land to repay loan (debt trap). (ii) Situation where credit pushes borrower into worse distress from which recovery is painful. (iii) Expand rural cooperative/bank branches & simplified Kisan Credit Cards. (iv) Primary Agricultural Credit Society (PACS) / Cooperative banks.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000e5', 'Rapid integration or interconnection between countries across trade, investment, and technology is called:', '{"A":"Privatisation","B":"Globalisation","C":"Nationalisation","D":"Urbanisation"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Globalisation and the Indian Economy', 1, 'Globalisation links economies via trade, MNC investment, and IT.', NULL, NULL, 'Globalisation links economies via trade, MNC investment, and IT.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000e6', 'A company that owns or controls production in more than one nation is called a:', '{"A":"Cooperative","B":"Multinational Corporation (MNC)","C":"Public Sector Undertaking","D":"Regional Trader"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Globalisation and the Indian Economy', 1, 'MNCs locate production where labour and resources are cost-effective.', NULL, NULL, 'MNCs locate production where labour and resources are cost-effective.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000e7', 'Tax levied by a government on imported goods to protect domestic producers is an example of a:', '{"A":"Subsidy","B":"Trade barrier","C":"Export incentive","D":"Exchange rate"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Globalisation and the Indian Economy', 1, 'Taxes on imports and quotas act as trade barriers.', NULL, NULL, 'Taxes on imports and quotas act as trade barriers.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000e8', 'Removing government-set barriers or restrictions on foreign trade and investment is termed:', '{"A":"Nationalisation","B":"Liberalisation","C":"Taxation","D":"Monopoly"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Globalisation and the Indian Economy', 1, 'India liberalised trade and investment policies significantly in 1991.', NULL, NULL, 'India liberalised trade and investment policies significantly in 1991.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000e9', 'Which major factor has rapidly enabled instant global communication, remote IT outsourcing, and logistics coordination?', '{"A":"Steam engine only","B":"Information and Communication Technology (ICT / Internet)","C":"Horse carriages","D":"Tariff barriers"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Globalisation and the Indian Economy', 1, 'Telecommunications, computers, and Internet shrunk global distance.', NULL, NULL, 'Telecommunications, computers, and Internet shrunk global distance.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ea', 'Assertion (A): India removed trade barriers around 1991 so Indian producers had to compete globally.
Reason (R): Policymakers believed global competition would improve the quality and efficiency of domestic Indian goods.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Social Science', 'Globalisation and the Indian Economy', 1, '1991 LPG reforms opened Indian markets to global quality benchmarks.', NULL, NULL, '1991 LPG reforms opened Indian markets to global quality benchmarks.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000eb', 'Why did the Indian Government put barriers to foreign trade and foreign investment soon after Independence?', NULL, NULL, 'VSA', 'Social Science', 'Globalisation and the Indian Economy', 2, 'To protect newly emerging domestic Indian industries from unfair competition by established foreign companies in the 1950s–60s (allowing imports only of essential machinery, fertilisers, petroleum).', 'Protection of nascent industries (2M)', NULL, 'To protect newly emerging domestic Indian industries from unfair competition by established foreign companies in the 1950s–60s (allowing imports only of essential machinery, fertilisers, petroleum).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000ec', 'State two ways in which Multi-National Corporations (MNCs) set up or control production in other countries.', NULL, NULL, 'VSA', 'Social Science', 'Globalisation and the Indian Economy', 2, 'Setting up factories jointly with local firms, buying up local companies (e.g., Cargill buying Parakh Foods), or placing large orders with small local producers globally (garments, footwear, sports).', 'Any 2 ways × 1M', NULL, 'Setting up factories jointly with local firms, buying up local companies (e.g., Cargill buying Parakh Foods), or placing large orders with small local producers globally (garments, footwear, sports).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000ed', 'Explain how Improvement in Transportation and Information & Communication Technology (ICT) has stimulated globalisation.', NULL, NULL, 'SA', 'Social Science', 'Globalisation and the Indian Economy', 3, 'Container shipping and lower air-freight costs made bulk global movement cheaper and faster; satellite communication, internet, e-banking, and email allow instant service delivery (call centres, software, magazine designing in India for London clients).', 'Transport (1.5M) + ICT (1.5M)', NULL, 'Container shipping and lower air-freight costs made bulk global movement cheaper and faster; satellite communication, internet, e-banking, and email allow instant service delivery (call centres, software, magazine designing in India for London clients).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000ee', 'How has Globalisation benefited well-off consumers and major Indian companies, while hurting some small manufacturers?', NULL, NULL, 'SA', 'Social Science', 'Globalisation and the Indian Economy', 3, 'Consumers enjoy wider choice, better quality, and lower prices (mobiles, cars, electronics); top Indian MNCs emerged (Tata Motors, Infosys, Ranbaxy). Meanwhile, small manufacturers of batteries, capacitors, plastics, toys, and tyres struggled to match cheap imports.', 'Benefits (1.5M) + Negative impact on small units (1.5M)', NULL, 'Consumers enjoy wider choice, better quality, and lower prices (mobiles, cars, electronics); top Indian MNCs emerged (Tata Motors, Infosys, Ranbaxy). Meanwhile, small manufacturers of batteries, capacitors, plastics, toys, and tyres struggled to match cheap imports.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000ef', 'Discuss the role of Liberalisation (1991 Reforms) in shaping Indian trade and investment. How can Government ensure "Fair Globalisation" so workers and small producers also gain?', NULL, NULL, 'LA', 'Social Science', 'Globalisation and the Indian Economy', 5, '1991 Liberalisation lifted import quotas/high tariffs and welcomed FDI so businesses could import/export freely and compete globally. Fair Globalisation steps: strictly enforce labour laws protecting workers'' rights & wages; support small producers with cheap credit, infrastructure, and modern tech until competitive; negotiate fair WTO rules with developing-nation allies (or impose strategic protective barriers if needed).', '1991 Liberalisation (2M) + Fair Globalisation steps (3M)', NULL, '1991 Liberalisation lifted import quotas/high tariffs and welcomed FDI so businesses could import/export freely and compete globally. Fair Globalisation steps: strictly enforce labour laws protecting workers'' rights & wages; support small producers with cheap credit, infrastructure, and modern tech until competitive; negotiate fair WTO rules with developing-nation allies (or impose strategic protective barriers if needed).', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000f0', '(i) Why do US/European MNCs locate design in the US, manufacturing in China, customer care in India, and assembly in Mexico/Eastern Europe? (ii) What cost saving do MNCs achieve this way? (iii) Give one reason India attracts global IT/call-centre outsourcing. (iv) Name one way local Indian suppliers benefit from partnering with MNCs.', NULL, NULL, 'CASE', 'Social Science', 'Globalisation and the Indian Economy', 4, '(i) Combining R&D skill, cheap Chinese manufacturing scale, proximity to US/EU markets, and skilled English-speaking Indian engineers. (ii) 50–60% production cost savings. (iii) Large pool of skilled English-speaking technical youth + lower costs. (iv) Capital investment, latest technology, and global supply access.', '4 × 1M = 4M', 'A global industrial electronics firm designs micro-components in California, gets them manufactured cheaply in China, ships components to Mexico and Eastern Europe for fast assembly near American/European markets, and handles customer support from Bengaluru.', '(i) Combining R&D skill, cheap Chinese manufacturing scale, proximity to US/EU markets, and skilled English-speaking Indian engineers. (ii) 50–60% production cost savings. (iii) Large pool of skilled English-speaking technical youth + lower costs. (iv) Capital investment, latest technology, and global supply access.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000f1', 'Who hosted the Congress of Vienna in 1815 after the defeat of Napoleon Bonaparte?', '{"A":"Giuseppe Mazzini","B":"Austrian Chancellor Duke Metternich","C":"Otto von Bismarck","D":"Victor Emmanuel II"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. In 1815, representatives of Britain, Russia, Prussia and Austria met at Vienna under the hosts of Austrian Chancellor Duke Metternich to draw up the Treaty of Vienna.', 'Identify Duke Metternich as host of 1815 Congress of Vienna [1 Mark]', NULL, 'Examiner Tip: Metternich remarked: "When France sneezes, the rest of Europe catches cold." | Common Pitfall: Confusing Metternich with Bismarck (who unified Germany later).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f2', 'Which of the following statements correctly describes the Zollverein formed in 1834?', '{"A":"A secret revolutionary society founded by Mazzini","B":"A customs union initiated by Prussia that abolished tariff barriers and reduced currencies from over thirty to two","C":"A military alliance against the Ottoman Empire","D":"A peasant organisation in Sicily"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. Formed in 1834 at Prussia''s initiative and joined by most German states, Zollverein abolished internal tariff barriers and reduced the number of currencies from over 30 to 2.', 'Prussian customs union reducing currencies 30+ to 2 [1 Mark]', NULL, 'Examiner Tip: Remember year 1834 and key achievement: currencies 30+ -> 2. | Common Pitfall: Confusing Zollverein with Young Europe.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f3', 'The Poona Pact of September 1932 was signed between Mahatma Gandhi and Dr. B.R. Ambedkar regarding:', '{"A":"Dominion status for India","B":"Reserved seats for Depressed Classes in provincial and central legislative councils within the general electorate","C":"Repeal of Rowlatt Act","D":"Partition of Bengal"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. Under the Poona Pact (September 1932), Depressed Classes (Scheduled Castes) were given reserved seats in legislative councils, to be voted in by the general electorate rather than separate electorates.', 'Reserved seats in councils voted by general electorate [1 Mark]', NULL, 'Examiner Tip: Gandhiji opposed separate electorates fearing division of society; Poona Pact resolved it. | Common Pitfall: Writing that Poona Pact granted separate electorates.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f4', 'Which disease devastated 90% of Africa''s cattle in the 1890s, forcing Africans into the colonial labour market?', '{"A":"Smallpox","B":"Rinderpest (cattle plague)","C":"Cholera","D":"Foot-and-mouth disease"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. Rinderpest, a fast-spreading cattle plague introduced via infected cattle from British Asia to feed Italian soldiers in Eritrea, killed 90% of cattle in Africa.', 'Identify Rinderpest cattle plague of 1890s [1 Mark]', NULL, 'Examiner Tip: Rinderpest destroyed African pastoral livelihoods and handed monopoly over cattle to colonisers. | Common Pitfall: Confusing Rinderpest (Africa cattle) with Smallpox (Americas).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f5', 'Who wrote the book "Gulamgiri" (1871) highlighting the injustices of the caste system in India?', '{"A":"B.R. Ambedkar","B":"Jyotiba Phule","C":"E.V. Ramaswamy Naicker (Periyar)","D":"Kashibaba"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. Jyotiba Phule, pioneer of low-caste protest movements, wrote "Gulamgiri" in 1871 and dedicated it to Americans who fought to free slaves.', 'Identify Jyotiba Phule as author of Gulamgiri (1871) [1 Mark]', NULL, 'Examiner Tip: Match authors cleanly: Gulamgiri = Jyotiba Phule; Chhote Aur Bade Ka Sawal = Kashibaba; Amar Jiban = Rashsundari Debi. | Common Pitfall: Attributing Gulamgiri to Dr. B.R. Ambedkar.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f6', 'The Vernacular Press Act of 1878 was modelled on the:', '{"A":"French Press Laws","B":"Irish Press Laws","C":"American First Amendment","D":"Russian Censorship Decree"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. Passed in 1878 after the Revolt of 1857, the Vernacular Press Act was modelled on the Irish Press Laws, giving the British government extensive rights to censor reports in Indian-language newspapers.', 'Identify Irish Press Laws [1 Mark]', NULL, 'Examiner Tip: Note the year 1878 and inspiration: Irish Press Laws. | Common Pitfall: Guessing French or British Common Law.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f7', 'Which soil type is known as "Regur soil", is ideal for growing cotton, and develops deep cracks during hot weather aiding proper aeration?', '{"A":"Alluvial Soil","B":"Black Soil","C":"Laterite Soil","D":"Arid Soil"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Geography', 1, 'Option (B) is correct. Black soil (Regur soil) covers the Deccan trap (basalt) region of Maharashtra, Saurashtra, Malwa and MP. Made of extremely fine clayey material, it holds moisture well and is ideal for cotton.', 'Identify Black (Regur) soil [1 Mark]', NULL, 'Examiner Tip: Black soil is rich in calcium carbonate, magnesium, potash and lime, but poor in phosphoric content. | Common Pitfall: Confusing Regur with Laterite soil.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f8', 'In which year was "Project Tiger", one of the most well-publicised wildlife conservation campaigns in the world, launched in India?', '{"A":"1972","B":"1973","C":"1980","D":"1991"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Geography', 1, 'Option (B) is correct. The Indian Wildlife (Protection) Act was implemented in 1972, followed by the launch of Project Tiger in 1973.', 'Identify 1973 for Project Tiger [1 Mark]', NULL, 'Examiner Tip: Wildlife Protection Act = 1972; Project Tiger = 1973. | Common Pitfall: Marking 1972 instead of 1973.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000f9', 'Which state in India was the FIRST to make rooftop rainwater harvesting structure compulsory for all houses across the state?', '{"A":"Rajasthan","B":"Meghalaya","C":"Tamil Nadu","D":"Gujarat"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Geography', 1, 'Option (C) is correct. Tamil Nadu is the first state in India which has made rooftop rainwater harvesting structure compulsory to all the houses across the state, with legal provisions to punish defaulters.', 'Identify Tamil Nadu [1 Mark]', NULL, 'Examiner Tip: Rajasthan uses tankas/khadins; Meghalaya uses 200-year-old bamboo drip irrigation; Tamil Nadu made rooftop RWH compulsory by law. | Common Pitfall: Selecting Rajasthan because of water scarcity.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000fa', 'Which of the following crops is a major Kharif crop grown with the onset of monsoon in different parts of India?', '{"A":"Wheat","B":"Mustard","C":"Rice (Paddy)","D":"Gram"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Geography', 1, 'Option (C) is correct. Paddy (rice), maize, jowar, bajra, cotton, jute and groundnut are Kharif crops harvested in September–October. Wheat, mustard, barley, peas and gram are Rabi crops.', 'Identify Rice (Paddy) as Kharif crop [1 Mark]', NULL, 'Examiner Tip: Rabi = winter (Oct-Dec sown); Kharif = monsoon (Jun-Jul sown); Zaid = short summer (watermelon, cucumber). | Common Pitfall: Marking Wheat as Kharif.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000fb', 'Which is the largest producer of manganese in India? / Which coal type has the highest carbon content and is the highest quality hard coal?', '{"A":"Peat","B":"Lignite","C":"Bituminous","D":"Anthracite"}'::jsonb, 'D', 'MCQ', 'Social Science', 'Geography', 1, 'Option (D) is correct. Anthracite is the highest quality hard coal with >80% carbon content. Bituminous is the most popular coal in commercial/metallurgical use.', 'Identify Anthracite as highest quality hard coal [1 Mark]', NULL, 'Examiner Tip: Order of coal quality (low to high): Peat -> Lignite -> Bituminous -> Anthracite. | Common Pitfall: Confusing Bituminous (most commercially used) with Anthracite (highest grade).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000fc', 'Which public sector agency markets steel for most public sector steel plants in India?', '{"A":"HAIL","B":"SAIL","C":"TATA Steel","D":"BHEL"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Geography', 1, 'Option (B) is correct. Steel Authority of India Limited (SAIL) markets steel for all public sector plants in India.', 'Identify SAIL [1 Mark]', NULL, 'Examiner Tip: Remember SAIL = Steel Authority of India Limited. | Common Pitfall: Selecting BHEL or TISCO (private sector).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000fd', 'In Belgium, besides the Central and State Governments, there is a third kind of government elected by people belonging to one language community (Dutch, French, or German). It is called:', '{"A":"Municipal Council","B":"Community Government","C":"Federal Assembly","D":"Linguistic Panchayat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Science', 1, 'Option (B) is correct. Belgium''s unique "Community Government" holds power regarding cultural, educational and language-related issues.', 'Identify Community Government in Belgium [1 Mark]', NULL, 'Examiner Tip: Brussels has equal representation of both Dutch and French communities. | Common Pitfall: Calling it Regional Government.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000fe', 'Which of the following subjects falls under the Concurrent List of the Indian Constitution?', '{"A":"Defence and Foreign Affairs","B":"Police and Agriculture","C":"Education, Forest and Marriage","D":"Banking and Currency"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Political Science', 1, 'Option (C) is correct. Education, Forests, Trade Unions, Marriage, Adoption and Succession are in the Concurrent List (both Union and State can make laws; Union law prevails in conflict).', 'Identify Education, Forest & Marriage in Concurrent List [1 Mark]', NULL, 'Examiner Tip: Union List = Defence, Banking, Currency, Foreign Affairs; State List = Police, Trade, Agriculture, Irrigation. | Common Pitfall: Placing Agriculture in Concurrent List.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ff', 'In India, at least one-third (33%) of seats are reserved for women in:', '{"A":"Rajya Sabha only","B":"Local government bodies — Panchayats and Municipalities","C":"Supreme Court Judges","D":"Cabinet Secretariat"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Science', 1, 'Option (B) is correct. The 73rd and 74th Constitutional Amendments (1992) legally mandated reservation of at least one-third of all positions for women in Panchayats and Municipalities. (Note: Nari Shakti Vandan Adhiniyam 2023 also proposes 33% in Lok Sabha & Assemblies.)', 'Identify Panchayats and Municipalities (local bodies) [1 Mark]', NULL, 'Examiner Tip: NCERT highlights local government bodies as having >10 lakh elected women representatives. | Common Pitfall: Confusing existing local body 1/3rd reservation with Rajya Sabha.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000100', 'According to the Election Commission of India, a "National Party" must secure at least 6% of total valid votes in Lok Sabha elections or Assembly elections in four States AND win at least:', '{"A":"2 seats in the Lok Sabha","B":"4 seats in the Lok Sabha","C":"10 seats in the Rajya Sabha","D":"6 seats in State Assemblies"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Science', 1, 'Option (B) is correct. Criteria for National Party: 6% of total votes in Lok Sabha/Assembly elections in 4 states AND win at least 4 seats in the Lok Sabha.', '6% votes in 4 states + minimum 4 Lok Sabha seats [1 Mark]', NULL, 'Examiner Tip: State Party rule: 6% votes in Legislative Assembly + at least 2 Assembly seats. | Common Pitfall: Mixing up 2 seats (State party) with 4 seats (National party).', 'EASY', true),
        ('10031111-0000-4000-8000-000000000101', 'Why is democracy considered a "legitimate" government even though it may be slower in decision-making than a dictatorship?', '{"A":"It guarantees highest GDP growth rate every year","B":"It is the people''s own elected government chosen through free and fair elections","C":"It removes all economic inequality immediately","D":"It eliminates political corruption completely"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Political Science', 1, 'Option (B) is correct. Democratic government may be slow or less efficient, but it is a legitimate government because citizens choose their rulers and hold them accountable.', 'Legitimacy arises from people''s own choice and consent [1 Mark]', NULL, 'Examiner Tip: Remember NCERT triad: Accountable, Responsive, and Legitimate government. | Common Pitfall: Claiming democracies always outperform dictatorships on economic growth rate.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000102', 'Besides per capita income, which two indicators are used by UNDP in the Human Development Report to compare countries?', '{"A":"Military budget and export surplus","B":"Educational levels (literacy/schooling) and Health status (life expectancy)","C":"Gold reserves and urban population","D":"Number of highways and airports"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Economics', 1, 'Option (B) is correct. Unlike the World Bank (which uses only Per Capita Income), UNDP''s Human Development Index compares countries on Per Capita Income, Health status (Life Expectancy at birth), and Educational levels.', 'Education levels + Health status (Life Expectancy) [1 Mark]', NULL, 'Examiner Tip: Contrast World Bank (only PCI) vs UNDP (PCI + Health + Education). | Common Pitfall: Selecting Infant Mortality Rate alone without Educational levels.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000103', 'Under MGNREGA 2005 ("Right to Work"), how many days of guaranteed wage employment in a year are assured by the government to every rural household whose adult members volunteer to do unskilled manual work?', '{"A":"50 days","B":"100 days","C":"150 days","D":"200 days"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Economics', 1, 'Option (B) is correct. MGNREGA 2005 guarantees 100 days of employment in a year in rural areas; if the government fails to provide employment, it pays unemployment allowances.', '100 days guaranteed wage employment [1 Mark]', NULL, 'Examiner Tip: Also remember the fallback clause: unemployment allowance if work is not provided within 15 days. | Common Pitfall: Selecting 150 days.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000104', 'Which institution supervises the functioning of formal sources of loans in India and ensures banks maintain a minimum cash balance?', '{"A":"NITI Aayog","B":"SEBI","C":"Reserve Bank of India (RBI)","D":"State Bank of India (SBI)"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Economics', 1, 'Option (C) is correct. RBI issues currency notes on behalf of the Central Government, supervises formal sector credit, monitors Cash Reserve Ratio (CRR), and ensures banks also lend to small cultivators and small borrowers.', 'Identify Reserve Bank of India (RBI) [1 Mark]', NULL, 'Examiner Tip: Informal lenders (moneylenders, traders) have NO supervising organisation like RBI. | Common Pitfall: Confusing RBI with SBI.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000105', 'How did the "Silk Routes" link distant parts of the pre-modern world? Give two examples of cultural or material exchange.', NULL, NULL, 'VSA', 'Social Science', 'History', 2, 'Silk routes were vibrant pre-modern land and sea trade networks linking Asia with Europe and Northern Africa since before the Christian Era until the 15th century.
1. Material exchange: Chinese silk cargoes, pottery, Indian textiles and spices travelled west, while gold and silver flowed from Europe to Asia.
2. Cultural exchange: Early Christian missionaries, Muslim preachers, and Buddhist monks from eastern India travelled along these routes.', 'Material goods exchange (silk/spices/gold) [1 Mark] | Religious & cultural exchange (Buddhism/missionaries) [1 Mark]', NULL, 'Examiner Tip: Mention both trade (silk, spices, precious metals) AND religion (Buddhism, Christianity, Islam). | Common Pitfall: Mentioning only silk trade.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000106', 'Differentiate between ferrous and non-ferrous minerals with one Indian example of each.', NULL, NULL, 'VSA', 'Social Science', 'Geography', 2, '1. Ferrous minerals contain iron and account for about three-fourths of total metallic mineral production; they provide a strong base for metallurgical industries. Example: Iron ore, Manganese.
2. Non-ferrous minerals do not contain iron and play a vital role in metallurgical, engineering and electrical industries. Example: Copper, Bauxite (Aluminium), Lead, Zinc.', 'Ferrous definition + example (Iron ore/Manganese) [1 Mark] | Non-ferrous definition + example (Copper/Bauxite) [1 Mark]', NULL, 'Examiner Tip: Specify "three-fourths of metallic production" as an NCERT anchor. | Common Pitfall: Listing coal or mica (non-metallic) as non-ferrous metals.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000107', 'Mention any two majoritarian measures adopted by the democratically elected Sri Lankan government under the 1956 Act that alienated the Sri Lankan Tamils.', NULL, NULL, 'VSA', 'Social Science', 'Political Science', 2, '1. The Act of 1956 recognised Sinhala as the only official language, completely disregarding Tamil.
2. The government followed preferential policies favouring Sinhala applicants for university positions and government jobs (and constitutionally vowed to protect and foster Buddhism).', 'Sinhala declared sole official language (1956 Act) [1 Mark] | Preferential job/university policy + Buddhism protection [1 Mark]', NULL, 'Examiner Tip: Always state the year 1956. | Common Pitfall: Writing Belgium policies by mistake.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000108', 'Why do we need to expand formal sources of credit in India, especially in rural areas? Give two reasons.', NULL, NULL, 'VSA', 'Social Science', 'Economics', 2, '1. Informal lenders (moneylenders, landlords) charge exorbitantly high interest rates and use unfair means, trapping borrowers in a debt trap.
2. Cheap and affordable credit from formal banks and cooperatives boosts income, allowing farmers and small entrepreneurs to invest in crops, equipment and small industries.', 'Prevent exploitation/debt trap of high informal interest [1 Mark] | Cheap credit promotes agriculture & small business growth [1 Mark]', NULL, 'Examiner Tip: Use the exact phrase "cheap and affordable credit is crucial for the country''s development". | Common Pitfall: Saying informal sector is supervised by RBI.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000109', 'Why did Mahatma Gandhi find in "salt" a powerful symbol that could unite the nation? Describe the start of the Civil Disobedience Movement.', NULL, NULL, 'SA', 'Social Science', 'History', 3, '1. Salt was consumed by both the rich and the poor alike as an essential item of daily food; the tax on salt and government monopoly revealed the most oppressive face of British rule.
2. After Viceroy Irwin ignored Gandhiji''s letter of 11 demands (31 Jan 1930), Gandhi started the historic 240-mile Dandi March on 12 March 1930 with 78 trusted volunteers from Sabarmati Ashram to coastal Dandi.
3. On 6 April 1930, he ceremonially violated the salt law by manufacturing salt by boiling seawater, launching the Civil Disobedience Movement.', 'Salt used by rich & poor + oppressive monopoly [1.5 Marks] | Dandi March (240 miles, 78 volunteers, 6 April 1930) [1.5 Marks]', NULL, 'Examiner Tip: Highlight key numbers: 11 demands, 78 volunteers, 240 miles, 24 days, 6 April 1930. | Common Pitfall: Mixing up Non-Cooperation (1920) with Civil Disobedience (1930).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000010a', 'Explain three major reasons why multi-purpose river valley projects and large dams have come under great scrutiny and opposition in recent years.', NULL, NULL, 'SA', 'Social Science', 'Geography', 3, '1. Ecological damage: Regulating and damming rivers affects natural flow causing poor sediment flow, excessive sedimentation at reservoir bottom, and rockier stream beds destroying aquatic habitats and blocking fish migration.
2. Displacement of communities: Reservoirs submerge existing vegetation and agricultural lands, displacing thousands of local farmers and tribal communities without adequate rehabilitation (e.g., Narmada Bachao Andolan).
3. Triggering floods & conflicts: Sedimentation in reservoirs can worsen floods during heavy rains and spark inter-state water disputes (e.g., Krishna-Godavari dispute).', 'Aquatic habitat & sedimentation impact [1 Mark] | Large-scale displacement & loss of livelihoods [1 Mark] | Inter-state disputes / flood risk / salinisation [1 Mark]', NULL, 'Examiner Tip: Remember Nehru called dams the "Temples of Modern India", yet ecological issues led to protests. | Common Pitfall: Listing only benefits when scrutiny/opposition is asked.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000010b', 'Mention any three key features that make India a federal country rather than a unitary state.', NULL, NULL, 'SA', 'Social Science', 'Political Science', 3, '1. Three-tier system of government: Union Government, State Governments, and a third tier of Panchayats and Municipalities (added in 1992).
2. Constitutional division of powers: Clearly specified legislative powers across Union List, State List, and Concurrent List.
3. Independent Judiciary & Rigid Amendment Process: The Supreme Court settles Centre-State disputes, and fundamental federal provisions cannot be changed unilaterally by Parliament — requiring 2/3rd majority plus ratification by at least half the State Legislatures.', '3-tier structure [1 Mark] | Threefold distribution of legislative powers [1 Mark] | Independent Judiciary / Bilateral amendment process [1 Mark]', NULL, 'Examiner Tip: Refer to Union, State and Concurrent Lists explicitly. | Common Pitfall: Saying "India has one single constitution so it is unitary".', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000010c', 'Explain how the Public Sector contributes to the economic development of a nation by giving three concrete examples.', NULL, NULL, 'SA', 'Social Science', 'Economics', 3, '1. Infrastructure creation: Things like roads, bridges, railways, harbours and electricity generation require massive spending beyond private capacity; the government builds and maintains these at reasonable cost.
2. Support to farmers & consumers: Government procures wheat and rice at Minimum Support Price (MSP) and sells at lower prices through Ration Shops (PDS) to ensure food security.
3. Human development essentials: Providing quality education, safe drinking water, affordable healthcare and housing for the poorest regions is a primary responsibility of the public sector.', 'Heavy infrastructure (railways/power/roads) [1 Mark] | Support to farmers & PDS food security [1 Mark] | Health, education & basic human welfare [1 Mark]', NULL, 'Examiner Tip: Contrast private sector profit motive with public sector social welfare motive. | Common Pitfall: Writing only "Public sector gives government jobs".', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000010d', 'How did the First World War (1914–1918) create a new economic and political situation in India?', NULL, NULL, 'SA', 'Social Science', 'History', 3, '1. Huge defence expenditure: Financed by war loans and increasing taxes — customs duties were raised and income tax was introduced.
2. Extreme price rise & forced recruitment: Prices doubled between 1913 and 1918 leading to severe hardship for common people, while forced recruitment in rural villages caused widespread anger.
3. Crop failure & epidemic: In 1918–19 and 1920–21, acute food shortages coincided with an influenza epidemic causing 12–13 million deaths according to the 1921 census.', 'Defence spending, income tax & customs duties [1 Mark] | Price doubling (1913-18) & forced rural recruitment [1 Mark] | Crop failures & 1921 influenza mortality [1 Mark]', NULL, 'Examiner Tip: Keep all 3 impacts sharp with exact years (1913–18, 1921 census). | Common Pitfall: Confusing WWI with WWII.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000010e', 'Describe the process of unification of Germany (1866–1871). Highlight the role of Otto von Bismarck and Prussia.', NULL, NULL, 'LA', 'Social Science', 'History', 5, '1. Failure of 1848 Liberal Initiative: Liberal middle-class Germans tried to unite German confederation states at the Frankfurt Parliament (1848), but were suppressed by monarchy, military and Junkers (large landowners of Prussia).
2. Prussia''s Leadership & Bismarck: Prussia then took charge of national unification. Its Chief Minister Otto von Bismarck was the architect of this process using the Prussian army and bureaucracy.
3. Three Wars over Seven Years: Bismarck fought three decisive wars against Austria, Denmark, and France (1864–1871), ending in complete Prussian victory.
4. Proclamation (January 1871): In the Hall of Mirrors at the Palace of Versailles, Prussian King William I was proclaimed German Emperor. The new nation emphasised modernising currency, banking, legal and judicial systems.', '1848 Frankfurt Parliament failure [1 Mark] | Bismarck + Prussian army & bureaucracy [1.5 Marks] | Three wars over 7 years (Austria, Denmark, France) [1.5 Marks] | Jan 1871 Versailles proclamation of Kaiser William I [1 Mark]', NULL, 'Examiner Tip: Always name the three opponents (Denmark, Austria, France) and Versailles Jan 1871. | Common Pitfall: Mixing up German unification (Bismarck, William I) with Italian unification (Cavour, Garibaldi, Mazzini).', 'HARD', true),
        ('10031111-0000-4000-8000-00000000010f', 'Explain five major human causes of land degradation in different states of India and suggest five practical conservation measures.', NULL, NULL, 'LA', 'Social Science', 'Geography', 5, 'Causes:
1. Deforestation due to mining (Jharkhand, Chhattisgarh, MP, Odisha) leaves deep scars and overburden.
2. Overgrazing in Gujarat, Rajasthan, MP and Maharashtra.
3. Over-irrigation in Punjab, Haryana and Western UP causing waterlogging and soil salinity/alkalinity.
4. Mineral processing (grinding limestone for cement/ceramic industries) releasing dust that blocks water infiltration.
5. Industrial effluents polluting land and water.
Conservation Measures:
1. Afforestation & proper management of grazing.
2. Planting shelter belts of plants & stabilising sand dunes with thorny bushes.
3. Control of mining activities.
4. Proper discharge and disposal of industrial wastes after treatment.
5. Contour ploughing, terrace farming and strip cropping on hilly slopes.', '3–5 state-specific causes of land degradation [2.5 Marks] | 5 distinct soil/land conservation measures [2.5 Marks]', NULL, 'Examiner Tip: Pairing exact Indian states (Punjab/Haryana -> over-irrigation; Jharkhand/Odisha -> mining) fetches full marks! | Common Pitfall: Repeating "plant trees" 3 times instead of distinct NCERT techniques.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000110', 'Identify and explain four major challenges faced by political parties in India, and mention one constitutional/legal reform already enacted to curb defection.', NULL, NULL, 'LA', 'Social Science', 'Political Science', 5, 'Four Challenges:
1. Lack of internal democracy: Concentration of power in one or few top leaders; no regular organisational elections or membership registers.
2. Dynastic succession: Top positions often controlled by members of one family, blocking ordinary workers from rising.
3. Growing role of money and muscle power: Parties nominate wealthy candidates or criminals during elections to ensure victory.
4. Lack of meaningful choice: Ideological differences among major parties have narrowed significantly.
Reform against Defection:
The Constitution was amended (Anti-Defection Law / 52nd Amendment) so that any elected MLA or MP who changes parties after election loses their seat in the legislature.', 'Four clearly explained challenges [4 Marks] | Anti-defection constitutional amendment [1 Mark]', NULL, 'Examiner Tip: Also remember Supreme Court''s mandatory affidavit rule disclosing property and pending criminal cases. | Common Pitfall: Listing voter apathy instead of the 4 NCERT party challenges.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000111', 'What are Self-Help Groups (SHGs)? Explain how SHGs help rural poor women overcome the problem of lack of collateral and achieve financial independence.', NULL, NULL, 'LA', 'Social Science', 'Economics', 5, '1. Structure of SHGs: A typical SHG has 15–20 members, usually belonging to one neighbourhood (mostly rural women), who meet and save regularly (₹25 to ₹100 or more per member).
2. Internal Loans at Reasonable Interest: Members can take small loans directly from the pooled group savings at interest rates much lower than moneylenders.
3. Bank Linkage Without Collateral: After 1–2 years of regular savings, the group becomes eligible for a formal bank loan sanctioned in the group''s name — helping poor women get timely loans WITHOUT physical collateral.
4. Self-Employment & Social Empowerment: Funds are used to release mortgaged land, buy sewing machines/cattle, and regular group meetings also serve as a platform to discuss health, nutrition and domestic violence.', '15-20 neighbourhood members & pooled savings [1 Mark] | Internal low-interest loans [1 Mark] | Bank loans without collateral after 1-2 yrs [2 Marks] | Social & economic empowerment [1 Mark]', NULL, 'Examiner Tip: Highlight the key phrase: "building blocks of organisation of the rural poor — helping borrowers overcome lack of collateral". | Common Pitfall: Writing that banks give free grants instead of repayable loans.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000112', 'Read the passage and answer:
From the mid-nineteenth century, lives and feelings of women began to be written in particularly vivid and intense ways. Rashsundari Debi, a young married girl in an orthodox Bengali household, learnt to read in the secrecy of her kitchen and later wrote her autobiography "Amar Jiban" (1876). Writers like Kailashbashini Debi, Tarabai Shinde and Pandita Ramabai also wrote passionately about the miserable lives of upper-caste Hindu women and widows.

(a) Name the first full-length autobiography published in the Bengali language and its author. (1M)
(b) Why did conservative Hindu and Muslim families initially fear educating girls? (1M)
(c) Mention the contribution of Tarabai Shinde and Pandita Ramabai in Maharashtra. (2M)', NULL, NULL, 'CASE', 'Social Science', 'Case Study', 4, '(a) "Amar Jiban" (1876) by Rashsundari Debi.
(b) Conservative Hindus believed a literate girl would become a widow, while orthodox Muslims feared educated women would be corrupted by reading Urdu romances.
(c) Tarabai Shinde and Pandita Ramabai from Maharashtra wrote with passionate anger about the miserable conditions and social injustices faced by upper-caste Hindu women, especially widows.', '(a) Amar Jiban (1876) by Rashsundari Debi [1 Mark] | (b) Conservative fears (widowhood / corruption) [1 Mark] | (c) Critique of upper-caste women & widow oppression [2 Marks]', NULL, 'Examiner Tip: Amar Jiban = 1876 (first full-length Bengali autobiography). | Common Pitfall: Confusing Rashsundari Debi with Rokeya Sakhawat Hossein.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000113', 'Read the passage and answer:
A major step towards decentralisation was taken in 1992 when the Constitution was amended to make the third-tier of democracy more powerful and effective. Now it is constitutionally mandatory to hold regular elections to local government bodies, seats are reserved for SC/ST/OBC and women, and an independent State Election Commission conducts these elections.

(a) What is the core idea behind decentralisation? (1M)
(b) What percentage of seats is reserved for women in Panchayats and Municipalities? (1M)
(c) Explain two powers/sources of revenue given to local governments under the 1992 Constitutional Amendment. (2M)', NULL, NULL, 'CASE', 'Social Science', 'Case Study', 4, '(a) When power is taken away from Central and State governments and given to local government, it is called decentralisation — because local people know local problems best.
(b) At least one-third (33%) of all positions are reserved for women.
(c) Under the 1992 amendment, State governments are required to share some powers and revenue with local government bodies (nature of sharing varies across states), and regular elections + State Election Commission ensure autonomous local governance.', '(a) Definition of decentralisation [1 Mark] | (b) One-third (33%) reservation [1 Mark] | (c) State revenue/power sharing & State Election Commission [2 Marks]', NULL, 'Examiner Tip: Distinguish Election Commission of India (Parliament/Assemblies) from State Election Commission (Panchayats/Municipalities). | Common Pitfall: Writing 50% as constitutional mandate instead of at least 1/3rd.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000114', 'Read the passage and answer:
Cargill Foods, a very large American MNC, bought over smaller Indian companies such as Parakh Foods, which had built a large marketing network and four oil refineries across India. Cargill is now the largest producer of edible oil in India with a capacity to make 5 million pouches daily.

(a) What is the most common route for MNC investments in developing countries, as illustrated above? (1M)
(b) Mention one other way in which MNCs spread their production across countries. (1M)
(c) Explain how MNCs integrate production and markets across nations, giving two points. (2M)', NULL, NULL, 'CASE', 'Social Science', 'Case Study', 4, '(a) Buying up local companies and then expanding production (e.g., Cargill buying Parakh Foods).
(b) Placing orders for production with small local producers (garments, footwear, sports items) or setting up joint partnerships with local companies.
(c) 1. MNCs bring massive capital, advanced technology, and global brand networks to local markets.
2. Foreign trade and MNC supply chains link producers and buyers across continents, giving consumers wider choice at competitive prices.', '(a) Buying local companies (Parakh Foods example) [1 Mark] | (b) Orders to small producers / Joint venture [1 Mark] | (c) Capital/technology transfer + market integration [2 Marks]', NULL, 'Examiner Tip: Recall the 3 NCERT MNC entry strategies: Joint partnership, Buying local firms, Placing orders with small producers. | Common Pitfall: Saying MNCs only build new greenfield factories.', 'HARD', true),
        ('10031111-0000-4000-8000-000000000115', '(A) Two places A and B are marked on the political outline map of India. Identify them:
  (i) Place where the Indian National Congress session of September 1920 was held.
  (ii) Place in Gujarat where Mahatma Gandhi broke the Salt Law in April 1930.
(B) On the same outline map of India, locate and label any THREE of the following:
  (i) Bhakra Nangal Dam
  (ii) Tarapur Nuclear Power Plant
  (iii) Bokaro Iron & Steel Plant
  (iv) Paradip Major Sea Port', NULL, NULL, 'MAP', 'Social Science', 'Map Skill (Section F)', 5, '(A) History Identification (2 Marks):
  (i) Calcutta (Kolkata, West Bengal) — Sept 1920 special INC session.
  (ii) Dandi (Navsari district, Gujarat) — Salt Satyagraha, 6 April 1930.
(B) Geography Location & Labelling (3 Marks):
  (i) Bhakra Nangal Dam: On Satluj river at Himachal Pradesh / Punjab border.
  (ii) Tarapur Nuclear Power Plant: Coastal Maharashtra (Palghar district, north of Mumbai).
  (iii) Bokaro Iron & Steel Plant: Eastern Jharkhand.
  (iv) Paradip Sea Port: Coastal Odisha on the Bay of Bengal.', '(A) Identify Calcutta (Sept 1920) & Dandi [2 Marks] | (B) Locate & label any 3 Geography features accurately [3 Marks]', NULL, 'Examiner Tip: Remember INC 1920 distinction: September 1920 = Calcutta; December 1920 = Nagpur; 1927 = Madras! | Common Pitfall: Confusing September 1920 (Calcutta) with December 1920 (Nagpur).', 'HARD', true),
        ('10031111-0000-4000-8000-000000000116', 'Tax on imports is an example of:', '{"A":"Collateral","B":"Trade barrier","C":"Foreign direct investment","D":"Terms of credit"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Economics', 1, 'Option (B) is correct. A tax on imports is called a trade barrier because governments use it to restrict or regulate foreign trade and protect domestic producers.', 'Identify import tax as trade barrier [1 Mark]', NULL, 'Examiner Tip: Removing government-set trade barriers is called "Liberalisation". | Common Pitfall: Confusing trade barrier with FDI.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000117', 'Why did Mahatma Gandhi call off the Non-Cooperation Movement in February 1922?', '{"A":"Jallianwala Bagh Massacre occurred","B":"The movement turned violent at Chauri Chaura in Gorakhpur where a peaceful demonstration clashed with police","C":"Simon Commission arrived in India","D":"Gandhi-Irwin Pact was signed"}'::jsonb, 'B', 'MCQ', 'Social Science', 'History', 1, 'Option (B) is correct. At Chauri Chaura (Gorakhpur, UP) in February 1922, a peaceful procession turned violent and set a police station ablaze, leading Gandhiji to halt the Non-Cooperation Movement as satyagrahis needed proper training in non-violence.', 'Chauri Chaura violent incident in Feb 1922 [1 Mark]', NULL, 'Examiner Tip: Jallianwala Bagh happened in 1919 (BEFORE NCM); Chauri Chaura happened in Feb 1922 (ENDED NCM). | Common Pitfall: Confusing Chauri Chaura with Gandhi-Irwin Pact (1931).', 'EASY', true),
        ('10031111-0000-4000-8000-000000000118', 'Why did Martin Luther say "Printing is the ultimate gift of God and the greatest one"?', NULL, NULL, 'VSA', 'Social Science', 'History', 2, 'In 1517, Martin Luther wrote his Ninety-Five Theses criticising practices of the Roman Catholic Church. Printed copies spread rapidly across Europe, triggering the Protestant Reformation and leading Luther''s German New Testament translation to sell 5,000 copies within weeks — proving print created a new intellectual public sphere.', 'Ninety-Five Theses (1517) rapid spread [1 Mark] | Protestant Reformation & wide public reach [1 Mark]', NULL, 'Examiner Tip: Mention 1517 and Ninety-Five Theses. | Common Pitfall: Confusing Luther with Gutenberg.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-000000000119', 'Suggest any three practical steps to minimise environmental degradation caused by manufacturing industries.', NULL, NULL, 'SA', 'Social Science', 'Geography', 3, '1. Water conservation & treatment: Minimising water use by reusing and recycling in successive stages, harvesting rainwater, and treating hot water/effluents through primary (mechanical), secondary (biological) and tertiary (chemical) stages before river discharge.
2. Air & particulate control: Fitting smokestacks with electrostatic precipitators, fabric filters, scrubbers and inertial separators, and using oil or gas instead of coal in factories.
3. Noise reduction: Fitting machinery and generators with silencers and using noise-absorbing materials.', '3-stage effluent treatment & water recycling [1 Mark] | Electrostatic precipitators / oil or gas fuel switch [1 Mark] | Silencers & acoustic insulation [1 Mark]', NULL, 'Examiner Tip: Use NCERT terms: "electrostatic precipitators", "scrubbers", and "three-stage effluent treatment". | Common Pitfall: Giving vague answers like "plant more trees" without industrial specifics.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000011a', 'How did cultural processes — symbols, folklore, icons and reinterpretation of history — help create a sense of collective belonging among Indians during the freedom struggle?', NULL, NULL, 'LA', 'Social Science', 'History', 5, '1. Allegory of Bharat Mata: First created by Bankim Chandra Chattopadhyay (who wrote Vande Mataram in Anandamath) and later painted by Abanindranath Tagore as a calm, ascetic, divine figure.
2. Indian Folklore Revival: Nationalists like Rabindranath Tagore in Bengal and Natesa Sastri in Madras (published "The Folklore of Southern India") recorded folk tales and ballads to preserve traditional national identity.
3. Icons and Flags: Swadeshi Movement tricolour (red, green, yellow with 8 lotuses and crescent moon) and Gandhiji''s 1921 Swaraj Flag (red, green, white with spinning wheel) became symbols of defiance.
4. Reinterpretation of History: Indian historians wrote proudly about ancient achievements in art, science, mathematics, law and trade before British colonisation.', 'Bharat Mata + Vande Mataram [1.5 Marks] | Folklore (Tagore & Natesa Sastri) [1.5 Marks] | Flags (Swadeshi & 1921 Swaraj Flag) [1 Mark] | Reinterpretation of glorious ancient history [1 Mark]', NULL, 'Examiner Tip: Cite exact names: Bankim Chandra, Abanindranath Tagore, Natesa Sastri. | Common Pitfall: Limiting answer only to Gandhi''s political movements.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000011b', 'Read the passage and answer:
In semi-arid and arid regions of Rajasthan (Bikaner, Phalodi and Barmer), almost all houses traditionally had underground tanks or "tankas" for storing drinking water. Built inside the main house or courtyard, they were connected to sloping roofs through pipes, storing the pure "palar pani".

(a) What is "palar pani" as referred to in arid Rajasthan? (1M)
(b) Why was the first spell of rain usually NOT collected in tankas? (1M)
(c) Name two traditional rainwater harvesting systems from other regions of India (e.g., Western Himalayas and Floodplains of Bengal). (2M)', NULL, NULL, 'CASE', 'Social Science', 'Case Study', 4, '(a) Rainwater, considered the purest form of natural water in arid Rajasthan.
(b) The first spell of rain was not collected because it washed and cleaned the roofs and pipes of dust and debris.
(c) 1. Western Himalayas: Diversion channels called "guls" or "kuls" for agriculture.
2. Floodplains of Bengal: Inundation channels to irrigate fields (also arid Jaisalmer "khadins" and other parts of Rajasthan "johads").', '(a) Rainwater (purest natural water) [1 Mark] | (b) Cleans roofs and pipes [1 Mark] | (c) Guls/Kuls (Himalayas) & Inundation channels (Bengal) [2 Marks]', NULL, 'Examiner Tip: Match exact regions: Himalayas = Guls/Kuls; Bengal = Inundation channels; Jaisalmer = Khadins. | Common Pitfall: Confusing Khadins (fields) with Tankas (drinking water tanks).', 'HARD', true),
        ('10031111-0000-4000-8000-00000000011c', '(A) Identify the two places A and B connected to the Indian National Movement:
  (i) Place in Bihar where Gandhiji organised Satyagraha for indigo planters (1917).
  (ii) City in Punjab where the Jallianwala Bagh massacre took place (13 April 1919).
(B) Locate and label any THREE of the following on the map of India:
  (i) Hirakud Dam
  (ii) Kalpakkam Nuclear Power Plant
  (iii) Bhilai Steel Plant
  (iv) Visakhapatnam Major Sea Port', NULL, NULL, 'MAP', 'Social Science', 'Map Skill (Section F)', 5, '(A) History Identification (2 Marks):
  (i) Champaran (Bihar) — 1917 Indigo Planters Satyagraha.
  (ii) Amritsar (Punjab) — 13 April 1919 Jallianwala Bagh.
(B) Geography Location & Labelling (3 Marks):
  (i) Hirakud Dam: On Mahanadi river in western Odisha.
  (ii) Kalpakkam Nuclear Plant: Tamil Nadu coast, south of Chennai.
  (iii) Bhilai Steel Plant: Central Chhattisgarh.
  (iv) Visakhapatnam Sea Port: Northern coast of Andhra Pradesh.', '(A) Champaran & Amritsar identified [2 Marks] | (B) 3 Geography locations accurately plotted [3 Marks]', NULL, 'Examiner Tip: Keep all 3 Satyagrahas clear: Champaran (1917 Indigo), Kheda (1917/18 Peasants), Ahmedabad (1918 Cotton Mill Workers). | Common Pitfall: Swapping Kheda with Champaran.', 'HARD', true),
        ('10031111-0000-4000-8000-00000000011d', 'State two key differences between Primitive Subsistence Farming and Commercial Farming in India.', NULL, NULL, 'VSA', 'Social Science', 'Geography', 2, '1. Primitive Subsistence Farming is practised on small patches of land using primitive tools (hoe, dao, digging sticks) and family labour, depending on monsoon and natural soil fertility (e.g., Jhumming).
2. Commercial Farming uses higher doses of modern inputs like HYV seeds, chemical fertilisers, insecticides and pesticides on larger holdings to obtain higher productivity for market sale (e.g., Plantation crops like tea/coffee or Punjab rice).', 'Tools/scale/monsoon dependence in Primitive [1 Mark] | HYV seeds, modern inputs & market focus in Commercial [1 Mark]', NULL, 'Examiner Tip: Mention "Jhumming" in North-East India as a regional name for slash-and-burn. | Common Pitfall: Confusing Intensive Subsistence with Commercial.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-00000000011e', '(A) Identify the two historical places marked on the political map of India:
  (i) Place where the Indian National Congress session of December 1920 was held.
  (ii) Place where the INC session of 1927 passed a resolution against the Simon Commission.
(B) Locate and label any THREE of the following:
  (i) Sardar Sarovar Dam
  (ii) Bailadila Iron Ore Mine
  (iii) Mumbai High / Digboi Oil Field
  (iv) Raja Sansi (Sri Guru Ram Dass Jee) International Airport', NULL, NULL, 'MAP', 'Social Science', 'Map Skill (Section F)', 5, '(A) History Identification (2 Marks):
  (i) Nagpur (Maharashtra) — Dec 1920 INC session.
  (ii) Madras / Chennai (Tamil Nadu) — 1927 INC session.
(B) Geography Location & Labelling (3 Marks):
  (i) Sardar Sarovar Dam: On Narmada river in eastern Gujarat.
  (ii) Bailadila Iron Ore Mine: Southern Chhattisgarh (Bastar region).
  (iii) Digboi Oil Field: Upper eastern Assam (or Mumbai High offshore Arabian Sea).
  (iv) Raja Sansi International Airport: Amritsar, Punjab.', '(A) Nagpur & Madras identified [2 Marks] | (B) Any 3 geography locations correctly plotted [3 Marks]', NULL, 'Examiner Tip: Verify exact airport names: Amritsar = Raja Sansi; Chennai = Meenambakkam; Kolkata = Netaji Subhash Chandra Bose. | Common Pitfall: Placing Bailadila in Odisha instead of southern Chhattisgarh.', 'HARD', true)
