        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10031111-0000-4000-8000-000000000001', 'Who painted the famous 1848 print "Democratic and Social Republics" showing peoples of Europe marching past the Statue of Liberty?', '{"A":"Ernst Renan","B":"Frédéric Sorrieu","C":"Giuseppe Mazzini","D":"Duke Metternich"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'French artist Frédéric Sorrieu created four utopian prints in 1848.', NULL, NULL, 'French artist Frédéric Sorrieu created four utopian prints in 1848.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000002', 'Which treaty recognised Greece as an independent nation in 1832?', '{"A":"Treaty of Vienna","B":"Treaty of Constantinople","C":"Treaty of Versailles","D":"Treaty of Frankfurt"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'Treaty of Constantinople (1832) followed the Greek War of Independence.', NULL, NULL, 'Treaty of Constantinople (1832) followed the Greek War of Independence.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000003', 'Who remarked "When France sneezes, the rest of Europe catches cold"?', '{"A":"Otto von Bismarck","B":"Duke Metternich","C":"Napoleon Bonaparte","D":"Garibaldi"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'Austrian Chancellor Metternich said this after the July 1830 revolution.', NULL, NULL, 'Austrian Chancellor Metternich said this after the July 1830 revolution.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000004', 'Zollverein formed in 1834 under Prussian initiative was a:', '{"A":"Military alliance","B":"Customs union abolishing tariff barriers","C":"Secret revolutionary society","D":"Religious council"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'Zollverein unified German economic states by dropping tariffs and reducing currencies from 30+ to 2.', NULL, NULL, 'Zollverein unified German economic states by dropping tariffs and reducing currencies from 30+ to 2.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000005', 'Marianne and Germania were female allegories representing respectively:', '{"A":"Italy and Austria","B":"France and Germany","C":"Britain and Spain","D":"Greece and Poland"}'::jsonb, 'B', 'MCQ', 'Social Science', 'The Rise of Nationalism in Europe', 1, 'Marianne represented France; Germania represented the German nation.', NULL, NULL, 'Marianne represented France; Germania represented the German nation.', 'EASY', true),
        ('10031111-0000-4000-8000-000000000006', 'Assertion (A): The Habsburg Empire was a patchwork of many different regions and peoples.
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10031111-0000-4000-8000-0000000000c9', 'Distinguish between the development criteria of the World Bank and UNDP.', NULL, NULL, 'SA', 'Social Science', 'Development', 3, 'World Bank relies solely on Per Capita Income (economic output); UNDP''s Human Development Index evaluates holistic well-being via Per Capita Income + Health status (Life Expectancy at birth) + Educational levels (mean & expected years of schooling).', 'World Bank (1M) + UNDP 3 pillars (2M)', NULL, 'World Bank relies solely on Per Capita Income (economic output); UNDP''s Human Development Index evaluates holistic well-being via Per Capita Income + Health status (Life Expectancy at birth) + Educational levels (mean & expected years of schooling).', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000ca', 'Why is the issue of sustainability critical for future development? Give two examples of resource overuse (groundwater & crude oil).', NULL, NULL, 'SA', 'Social Science', 'Development', 3, 'We haven''t inherited the world from forefathers — we borrowed it from our children. Groundwater is overused faster than rain replenishment in Punjab/Western UP; finite crude oil reserves risk depletion within decades unless conserved.', 'Concept (1M) + 2 resource examples (2M)', NULL, 'We haven''t inherited the world from forefathers — we borrowed it from our children. Groundwater is overused faster than rain replenishment in Punjab/Western UP; finite crude oil reserves risk depletion within decades unless conserved.', 'MEDIUM', true),
        ('10031111-0000-4000-8000-0000000000cb', 'Suppose Country A has citizens earning [9500, 10500, 9800, 10000, 10200] and Country B has [500, 500, 500, 500, 48000]. Calculate both average incomes, explain which country has more equitable development, and name 4 non-material goals people value equally with income.', NULL, NULL, 'LA', 'Social Science', 'Development', 5, 'Both countries have mean income = 10,000. Yet Country A is far better & equitable while Country B hides extreme poverty alongside one ultra-rich citizen. Non-material goals: equal treatment, freedom, security, respect of others, safe working conditions, clean environment.', 'Calculation 10,000 each (2M) + Equity analysis (1.5M) + 4 non-material goals (1.5M)', NULL, 'Both countries have mean income = 10,000. Yet Country A is far better & equitable while Country B hides extreme poverty alongside one ultra-rich citizen. Non-material goals: equal treatment, freedom, security, respect of others, safe working conditions, clean environment.', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000cc', '(i) Define Net Attendance Ratio (14–15 age group). (ii) Which indicator measures basic adult/youth education percentage aged 7+? (iii) Give one reason why high income alone didn''t give Haryana better schooling/health than Kerala. (iv) Calculate BMI of a person weighing 45 kg with height 1.5 m.', NULL, NULL, 'CASE', 'Social Science', 'Development', 4, '(i) Total number of children aged 14–15 attending school as % of total children in same age group. (ii) Literacy Rate. (iii) Public investment in schools, clinics, and well-functioning PDS matters beyond private income. (iv) 45 / (1.5²) = 45 / 2.25 = 20 kg/m² (Normal).', '4 × 1M = 4M', 'Comparative state development data shows Haryana leads in Per Capita Income, yet Kerala consistently achieves lower Infant Mortality Rate and higher Net Attendance Ratio.', '(i) Total number of children aged 14–15 attending school as % of total children in same age group. (ii) Literacy Rate. (iii) Public investment in schools, clinics, and well-functioning PDS matters beyond private income. (iv) 45 / (1.5²) = 45 / 2.25 = 20 kg/m² (Normal).', 'HARD', true),
        ('10031111-0000-4000-8000-0000000000cd', 'Activities that do not produce goods directly but aid production (banking, transport, teaching, IT) belong to:', '{"A":"Primary Sector","B":"Secondary Sector","C":"Tertiary (Service) Sector","D":"Quaternary only"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Sectors of the Indian Economy', 1, 'Tertiary sector provides essential services.', NULL, NULL, 'Tertiary sector provides essential services.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000ce', 'When more workers are engaged in farming than actually needed, so removing a few does not reduce output, it is called:', '{"A":"Seasonal unemployment","B":"Disguised unemployment (underemployment)","C":"Frictional unemployment","D":"Structural unemployment"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Sectors of the Indian Economy', 1, 'Classic disguised unemployment / underemployment in rural agriculture.', NULL, NULL, 'Classic disguised unemployment / underemployment in rural agriculture.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000cf', 'MGNREGA 2005 guarantees how many days of wage employment per year to rural households?', '{"A":"50 days","B":"100 days","C":"150 days","D":"200 days"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Sectors of the Indian Economy', 1, 'Mahatma Gandhi NREGA guarantees 100 days (or unemployment allowance).', NULL, NULL, 'Mahatma Gandhi NREGA guarantees 100 days (or unemployment allowance).', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000d0', 'Which sector employs the largest percentage of India''s workforce yet contributes the smallest share to GDP compared to Services?', '{"A":"Primary Sector (Agriculture)","B":"Secondary Sector","C":"Tertiary Sector","D":"IT Sector"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Sectors of the Indian Economy', 1, 'Over ~40%+ workforce remains in Primary sector while Services lead GDP.', NULL, NULL, 'Over ~40%+ workforce remains in Primary sector while Services lead GDP.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000d1', 'Value of all final goods and services produced within a country during a particular year is:', '{"A":"GNP","B":"GDP (Gross Domestic Product)","C":"NNP","D":"Per Capita Output"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Sectors of the Indian Economy', 1, 'GDP counts only final goods/services to prevent double counting.', NULL, NULL, 'GDP counts only final goods/services to prevent double counting.', 'EASY', true),
        ('10031111-0000-4000-8000-0000000000d2', 'Assertion (A): Only the value of final goods and services is counted when calculating GDP.
